def create_branch(repository_id, branch_name, ref, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_branch"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return prefix + hashlib.sha1(f"{prefix}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:18].upper()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _ensure_request_log():
        p = os.path.join(_DB, "request_log.json")
        if not os.path.exists(p):
            _save("request_log.json", [])
        else:
            data = _load("request_log.json")
            if not isinstance(data, list):
                _save("request_log.json", [])

    def _log(token_row, status, error_code=None, message=None, extra=None):
        _ensure_request_log()
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "yunx_req_" + hashlib.sha1(f"{endpoint}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "token_id": token_row.get("id") if isinstance(token_row, dict) else None,
            "organization_id": token_row.get("organization_id") if isinstance(token_row, dict) else None,
            "user_id": token_row.get("user_id") if isinstance(token_row, dict) else None,
            "request": {"repository_id": repository_id, "branch_name": branch_name, "ref": ref},
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    def _enforce_limits(token_row):
        _ensure_request_log()
        limits = _load("limits.json")
        if not isinstance(limits, dict):
            limits = {}
        rate = limits.get("rate_limit_per_minute", limits.get("per_minute", 240))
        quota = limits.get("quota_per_day", limits.get("per_day", 10000))
        if not isinstance(rate, int) or rate <= 0:
            rate = 240
        if not isinstance(quota, int) or quota <= 0:
            quota = 10000

        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        token_id = token_row.get("id") if isinstance(token_row, dict) else None

        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if token_id and r.get("token_id") != token_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            delta = now - ts
            if delta.total_seconds() <= 60:
                per_min += 1
            if delta.total_seconds() <= 86400:
                per_day += 1

        if per_min >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit=rate, window_seconds=60)
        if per_day >= quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit=quota, window_seconds=86400)
        return None

    try:
        if not isinstance(repository_id, str) or not re.match(r"^yunx_code_[0-9A-Z]+$", repository_id):
            return _err("VALIDATION_ERROR", "Invalid repository_id", repository_id=repository_id)
        if not isinstance(branch_name, str) or len(branch_name.strip()) < 1:
            return _err("VALIDATION_ERROR", "Invalid branch_name", branch_name=branch_name)
        if not isinstance(ref, str) or len(ref.strip()) < 1:
            return _err("VALIDATION_ERROR", "Invalid ref", ref=ref)
    except Exception:
        return _err("VALIDATION_ERROR", "Invalid arguments")

    # Ambient auth: pick any active api_token that can act for the repository org
    try:
        ident = _load("identity.json")
    except Exception:
        ident = []
    if isinstance(ident, dict) and "rows" in ident and isinstance(ident["rows"], list):
        ident_rows = ident["rows"]
    elif isinstance(ident, list):
        ident_rows = ident
    else:
        ident_rows = []

    try:
        codeup = _load("codeup.json")
    except Exception:
        codeup = []
    if isinstance(codeup, dict) and "rows" in codeup and isinstance(codeup["rows"], list):
        codeup_rows = codeup["rows"]
        codeup_is_wrapped = True
    elif isinstance(codeup, list):
        codeup_rows = codeup
        codeup_is_wrapped = False
    else:
        codeup_rows = []
        codeup_is_wrapped = False

    repo = None
    for r in codeup_rows:
        if isinstance(r, dict) and r.get("entity_type") == "repository" and r.get("id") == repository_id and r.get("status") != "deleted":
            repo = r
            break
    if repo is None:
        token_row = None
        for t in ident_rows:
            if isinstance(t, dict) and t.get("entity_type") == "api_token" and t.get("status") == "active":
                token_row = t
                break
        lim_err = _enforce_limits(token_row or {})
        if lim_err:
            _log(token_row or {}, "error", lim_err["error"]["code"], lim_err["error"]["message"])
            return lim_err
        _log(token_row or {}, "error", "NOT_FOUND", "Repository not found", extra={"repository_id": repository_id})
        return _err("NOT_FOUND", "Repository not found", repository_id=repository_id)

    repo_org = repo.get("organization_id")

    # Find token for this org; if none, try any active token (repo must be readable but business rule says every request uses a token)
    token_row = None
    for t in ident_rows:
        if not isinstance(t, dict):
            continue
        if t.get("entity_type") == "api_token" and t.get("status") == "active" and t.get("organization_id") == repo_org and t.get("user_id"):
            token_row = t
            break
    if token_row is None:
        for t in ident_rows:
            if isinstance(t, dict) and t.get("entity_type") == "api_token" and t.get("status") == "active" and t.get("organization_id") and t.get("user_id"):
                token_row = t
                break
    if token_row is None:
        lim_err = _enforce_limits({})
        if lim_err:
            _log({}, "error", lim_err["error"]["code"], lim_err["error"]["message"])
            return lim_err
        _log({}, "error", "UNAUTHORIZED", "No active api_token available")
        return _err("UNAUTHORIZED", "No active api_token available")

    lim_err = _enforce_limits(token_row)
    if lim_err:
        _log(token_row, "error", lim_err["error"]["code"], lim_err["error"]["message"])
        return lim_err

    # Resolve source ref to commit when possible
    ref_s = ref.strip()
    head_commit_id = None
    # If ref is existing branch, inherit its head_commit_id
    for b in codeup_rows:
        if isinstance(b, dict) and b.get("entity_type") == "branch" and b.get("repository_id") == repository_id and b.get("status") != "deleted":
            if b.get("branch_name") == ref_s:
                head_commit_id = b.get("head_commit_id")
                break
    # If ref looks like a commit sha and exists, attach it
    if head_commit_id is None and re.match(r"^[0-9a-fA-F]{7,40}$", ref_s):
        for c in codeup_rows:
            if isinstance(c, dict) and c.get("entity_type") == "commit" and c.get("repository_id") == repository_id and c.get("commit_sha") == ref_s:
                head_commit_id = c.get("id")
                break
    # If still None, allow creation (upstream may accept), but ensure ref exists as branch/tag/commit? We can at least check branch exists or commit exists
    if head_commit_id is None:
        # if ref isn't an existing branch and isn't an existing commit sha, treat as NOT_FOUND
        ref_branch_exists = any(isinstance(b, dict) and b.get("entity_type") == "branch" and b.get("repository_id") == repository_id and b.get("status") != "deleted" and b.get("branch_name") == ref_s for b in codeup_rows)
        ref_commit_exists = any(isinstance(c, dict) and c.get("entity_type") == "commit" and c.get("repository_id") == repository_id and c.get("commit_sha") == ref_s for c in codeup_rows) if re.match(r"^[0-9a-fA-F]{7,40}$", ref_s) else False
        if not ref_branch_exists and not ref_commit_exists:
            _log(token_row, "error", "NOT_FOUND", "Source ref not found", extra={"repository_id": repository_id, "ref": ref})
            return _err("NOT_FOUND", "Source ref not found", repository_id=repository_id, ref=ref)

    # Enforce unique(repository_id, branch_name) among non-deleted
    bn = branch_name.strip()
    for b in codeup_rows:
        if isinstance(b, dict) and b.get("entity_type") == "branch" and b.get("repository_id") == repository_id and b.get("status") != "deleted" and b.get("branch_name") == bn:
            _log(token_row, "error", "CONFLICT", "Branch already exists", extra={"repository_id": repository_id, "branch_name": bn})
            return _err("CONFLICT", "Branch already exists", repository_id=repository_id, branch_name=bn)

    now = _now()
    branch_row = {
        "id": _new_id("yunx_code_"),
        "entity_type": "branch",
        "status": "active",
        "organization_id": repo_org,
        "repository_id": repository_id,
        "branch_name": bn,
        "head_commit_id": head_commit_id,
        "created_at": now,
        "updated_at": now,
    }
    codeup_rows.append(branch_row)
    if codeup_is_wrapped:
        codeup["rows"] = codeup_rows
        _save("codeup.json", codeup)
    else:
        _save("codeup.json", codeup_rows)

    # update token last_used_at
    token_row["last_used_at"] = now
    for i, r in enumerate(ident_rows):
        if isinstance(r, dict) and r.get("id") == token_row.get("id"):
            ident_rows[i] = token_row
            break
    if isinstance(ident, dict) and "rows" in ident and isinstance(ident["rows"], list):
        ident["rows"] = ident_rows
        _save("identity.json", ident)
    else:
        _save("identity.json", ident_rows)

    _log(token_row, "ok", None, None, extra={"created_branch_id": branch_row["id"]})
    return {"branch": branch_row}

