    if token_row is None:
        for t in ident_rows:
            if isinstance(t, dict) and t.get("entity_type") == "api_token" and t.get("status") == "active" and t.get("organization_id") and t.get("user_id"):
                token_row = t
                break
    if token_row is None:
        lim_err = _enforce_limits({})
        if lim_err:
            _log({}, "error", lim_err["error"]["code"], lim_err["error"]["message"])
            return lim_err
        _log({}, "error", "UNAUTHORIZED", "No active api_token available")
        return _err("UNAUTHORIZED", "No active api_token available")

    lim_err = _enforce_limits(token_row)
    if lim_err:
        _log(token_row, "error", lim_err["error"]["code"], lim_err["error"]["message"])
        return lim_err

    if repo is None:
        _log(token_row, "error", "NOT_FOUND", "Repository not found", extra={"repository_id": repository_id})
        return _err("NOT_FOUND", "Repository not found", repository_id=repository_id)

    bn = branch_name.strip()
    idx = None
    for i, b in enumerate(codeup_rows):
        if isinstance(b, dict) and b.get("entity_type") == "branch" and b.get("repository_id") == repository_id and b.get("branch_name") == bn:
            idx = i
            break
    if idx is None:
        _log(token_row, "error", "NOT_FOUND", "Branch not found", extra={"repository_id": repository_id, "branch_name": bn})
        return _err("NOT_FOUND", "Branch not found", repository_id=repository_id, branch_name=bn)

    branch = codeup_rows[idx]
    if branch.get("status") == "deleted":
        # idempotent-ish: if already deleted treat as NOT_FOUND for user-facing delete
        _log(token_row, "error", "NOT_FOUND", "Branch not found", extra={"repository_id": repository_id, "branch_name": bn})
        return _err("NOT_FOUND", "Branch not found", repository_id=repository_id, branch_name=bn)

    now = _now()
    branch["status"] = "deleted"
    branch["updated_at"] = now
    codeup_rows[idx] = branch

    if codeup_wrapped:
        codeup["rows"] = codeup_rows
        _save("codeup.json", codeup)
    else:
        _save("codeup.json", codeup_rows)

    token_row["last_used_at"] = now
    for i, r in enumerate(ident_rows):
        if isinstance(r, dict) and r.get("id") == token_row.get("id"):
            ident_rows[i] = token_row
            break
    if ident_wrapped:
        ident["rows"] = ident_rows
        _save("identity.json", ident)
    else:
        _save("identity.json", ident_rows)

    _log(token_row, "ok", extra={"deleted_branch_id": branch.get("id")})
    return {"branch": branch}

def list_branches(repository_id, search=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status, credential_id=None, organization_id=None, user_id=None, error_code=None):
        logs = _load("request_log.json")
        entry = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "list_branches",
            "status": status,
            "error_code": error_code,
            "credential_id": credential_id,
            "organization_id": organization_id,
            "user_id": user_id,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "request": {
                "repository_id": repository_id,
                "search": search,
                "limit": limit,
                "cursor": cursor,
                "sort": sort,
                "order": order,
            },
        }
        if isinstance(logs, list):
            logs.append(entry)
            _save("request_log.json", logs)

    def _rate_limit_check(credential_id):
        cfg = None
        for fn in ("quota.json", "rate_limit.json", "limits.json"):
            cand = _load(fn)
            if isinstance(cand, dict):
                cfg = cand
                break
        if not cfg:
            return None
        per_min = cfg.get("per_minute")
        if not isinstance(per_min, int) or per_min <= 0:
            return None
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(minutes=1)
        cnt = 0
        for r in logs[::-1]:
            if r.get("credential_id") != credential_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None or ts < cutoff:
                continue
            cnt += 1
            if cnt >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    t0 = time.time()

    if not isinstance(repository_id, str) or not re.match(r"^yunx_code_[0-9A-Z]+$", repository_id or ""):
        out = _err("VALIDATION_ERROR", "Invalid repository_id")
        _log("error", error_code="VALIDATION_ERROR")
        return out
    if search is not None and not isinstance(search, str):
        out = _err("VALIDATION_ERROR", "Invalid search")
        _log("error", error_code="VALIDATION_ERROR")
        return out
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        out = _err("VALIDATION_ERROR", "Invalid limit")
        _log("error", error_code="VALIDATION_ERROR")
        return out
    if sort is None:
        sort = "updated_at"
    if sort not in ("updated_at", "created_at", "branch_name"):
        out = _err("VALIDATION_ERROR", "Invalid sort")
        _log("error", error_code="VALIDATION_ERROR")
        return out
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        out = _err("VALIDATION_ERROR", "Invalid order")
        _log("error", error_code="VALIDATION_ERROR")
        return out

    cur = None
    if cursor is not None:
        cur = _decode_cursor(cursor)
        if cur is None:
            out = _err("VALIDATION_ERROR", "Invalid cursor")
            _log("error", error_code="VALIDATION_ERROR")
            return out
        # Basic shape validation
        if cur.get("repository_id") != repository_id or cur.get("sort") != sort or cur.get("order") != order:
            out = _err("VALIDATION_ERROR", "Cursor does not match query")
            _log("error", error_code="VALIDATION_ERROR")
            return out

    identity = _load("identity.json")
    codeup = _load("codeup.json")

    token = None
    for row in identity if isinstance(identity, list) else []:
        if row.get("entity_type") != "api_token" or row.get("status") != "active":
            continue
        if not row.get("organization_id") or not row.get("user_id"):
            continue
        scopes = row.get("token_scopes")
        if scopes is None:
            token = row
            break
        if isinstance(scopes, list) and ("code.read" in scopes or "code.*" in scopes or "*" in scopes or "code.write" in scopes):
            token = row
            break
    if not token:
        out = _err("UNAUTHORIZED", "No active API token available for this request")
        _log("error", error_code="UNAUTHORIZED")
        return out

    rl = _rate_limit_check(token.get("id"))
    if rl:
        _log("error", credential_id=token.get("id"), organization_id=token.get("organization_id"), user_id=token.get("user_id"), error_code=rl["error"]["code"])
        return rl

    org_id = token.get("organization_id")
    user_id = token.get("user_id")

    repo = None
    for r in codeup if isinstance(codeup, list) else []:
        if r.get("id") == repository_id and r.get("entity_type") == "repository" and r.get("organization_id") == org_id and r.get("status") != "deleted":
            repo = r
            break
    if not repo:
        out = _err("NOT_FOUND", "Repository not found")
        _log("error", credential_id=token.get("id"), organization_id=org_id, user_id=user_id, error_code="NOT_FOUND")
        return out

    has_membership = False
    for r in identity if isinstance(identity, list) else []:
        if r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("organization_id") == org_id and r.get("user_id") == user_id:
            has_membership = True
            break
    if not has_membership:
        out = _err("UNAUTHORIZED", "User is not an active member of the organization")
        _log("error", credential_id=token.get("id"), organization_id=org_id, user_id=user_id, error_code="UNAUTHORIZED")
        return out

    rows = []
    for r in codeup if isinstance(codeup, list) else []:
        if r.get("entity_type") != "branch":
            continue
        if r.get("organization_id") != org_id:
            continue
        if r.get("repository_id") != repository_id:
            continue
        if r.get("status") == "deleted":
            continue
        bn = r.get("branch_name") or ""
        if search and search not in bn:
            continue
        rows.append(r)

    # Sorting
    reverse = (order == "desc")

    def _key(r):
        if sort == "branch_name":
            return (r.get("branch_name") or "").lower()
        if sort == "created_at":
            dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1)
            return dt
        dt = _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1)
        return dt

    rows.sort(key=_key, reverse=reverse)

    # Cursor pagination: cursor contains last_value and last_id for stable pagination
    start = 0
    if cur:
        last_id = cur.get("last_id")
        last_val = cur.get("last_val")
        # Find first item strictly after cursor in the sorted order
        for i, r in enumerate(rows):
            kval = _key(r)
            kval_ser = kval.isoformat() if isinstance(kval, datetime.datetime) else kval
            if reverse:
                if kval_ser < last_val or (kval_ser == last_val and r.get("id") < last_id):
                    start = i
                    break
            else:
                if kval_ser > last_val or (kval_ser == last_val and r.get("id") > last_id):
                    start = i
                    break
        else:
            start = len(rows)

    page = rows[start : start + limit]
    has_more = start + limit < len(rows)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        kval = _key(last)
        kval_ser = kval.isoformat() if isinstance(kval, datetime.datetime) else kval
        next_cursor = _encode_cursor(
            {
                "repository_id": repository_id,
                "sort": sort,
                "order": order,
                "last_val": kval_ser,
                "last_id": last.get("id"),
            }
        )

    now = _now()
    # Update token last_used_at
    updated = False
    for r in identity if isinstance(identity, list) else []:
        if r.get("id") == token.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now if _parse_dt(r.get("updated_at")) is None or _parse_dt(r.get("updated_at")) <= _parse_dt(now) else r.get("updated_at")
            updated = True
            break
    if updated:
        _save("identity.json", identity)

    _log("ok", credential_id=token.get("id"), organization_id=org_id, user_id=user_id)
    return {
        "branches": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
        },
    }

def get_file_blobs(repository_id, path, ref, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_file_blobs"
    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _ensure_request_log():
        p = os.path.join(_DB, "request_log.json")
        if not os.path.exists(p):
            _save("request_log.json", [])
            return []
        d = _load("request_log.json")
        if not isinstance(d, list):
            _save("request_log.json", [])
            return []
        return d

    def _log(token_row, status, error_code=None, message=None, extra=None):
        logs = _ensure_request_log()
        row = {
            "id": "yunx_req_" + hashlib.sha1(f"{endpoint}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "token_id": token_row.get("id") if isinstance(token_row, dict) else None,
            "organization_id": token_row.get("organization_id") if isinstance(token_row, dict) else None,
            "user_id": token_row.get("user_id") if isinstance(token_row, dict) else None,
            "request": {"repository_id": repository_id, "path": path, "ref": ref},
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    def _resolve_token_context():
        identities = _load("identity.json")
        if not isinstance(identities, list):
            identities = []
        # ambient auth: pick any active api_token with valid user/org and active membership
        for tok in identities:
            if tok.get("entity_type") != "api_token" or tok.get("status") != "active":
                continue
            uid = tok.get("user_id")
            oid = tok.get("organization_id")
            if not isinstance(uid, str) or not uid or not isinstance(oid, str) or not oid:
                continue
            u = next((r for r in identities if r.get("id") == uid and r.get("entity_type") == "user" and r.get("status") == "active"), None)
            o = next((r for r in identities if r.get("id") == oid and r.get("entity_type") == "organization" and r.get("status") == "active"), None)
            if not u or not o:
                continue
            m = next((r for r in identities if r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("user_id") == uid and r.get("organization_id") == oid), None)
            if not m:
                continue
            exp = tok.get("expires_at")
            if isinstance(exp, str) and exp:
                exp_dt = _parse_dt(exp)
                if exp_dt is not None and exp_dt <= datetime.datetime.utcnow():
                    continue
            return tok, u, o
        return None, None, None

    def _rate_limit_check(token_row):
        # enforce simple per-token rate limit using request_log.json
        if not isinstance(token_row, dict):
            return None
        logs = _ensure_request_log()
        token_id = token_row.get("id")
        if not isinstance(token_id, str) or not token_id:
            return None
        window_sec = 60
        limit = 120
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_sec)
        cnt = 0
        # scan tail for efficiency
        for r in reversed(logs[-5000:]):
            if r.get("token_id") != token_id:
                continue
            dt = _parse_dt(r.get("timestamp"))
            if not dt:
                continue
            if dt >= cutoff:
                cnt += 1
                if cnt >= limit:
                    return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_sec, limit=limit)
            else:
                # logs are append-only; may not be strictly ordered, so don't break
                continue
        return None

    # Validate inputs
    if not isinstance(repository_id, str) or re.match(r"^yunx_code_[0-9A-Z]+$", repository_id) is None:
        tok, _, _ = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid repository_id")
        return _err("VALIDATION_ERROR", "Invalid repository_id", repository_id=repository_id)
    if not isinstance(path, str) or len(path) < 1:
        tok, _, _ = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid path")
        return _err("VALIDATION_ERROR", "Invalid path", path=path)
    if not isinstance(ref, str) or len(ref) < 1:
        tok, _, _ = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid ref")
        return _err("VALIDATION_ERROR", "Invalid ref", ref=ref)

    token_row, token_user, token_org = _resolve_token_context()
    if token_row is None:
        _log(None, "error", "UNAUTHORIZED", "No active token context available")
        return _err("UNAUTHORIZED", "Token is missing or invalid")

    rl = _rate_limit_check(token_row)
    if rl:
        _log(token_row, "error", "RATE_LIMIT", rl["error"]["message"])
        return rl

    # Authorization rule: token must be active and map to org; repository must belong to token org
    codeup = _load("codeup.json")
    if not isinstance(codeup, list):
        codeup = []

    repo = next((r for r in codeup if r.get("entity_type") == "repository" and r.get("id") == repository_id and r.get("status") != "deleted"), None)
    if repo is None:
        _log(token_row, "error", "NOT_FOUND", "Repository not found")
        return _err("NOT_FOUND", "Repository not found", repository_id=repository_id)

    if repo.get("organization_id") != token_row.get("organization_id"):
        _log(token_row, "error", "UNAUTHORIZED", "Token not authorized for this repository")
        return _err("UNAUTHORIZED", "No active token authorized for this repository")

    # Resolve file at (repository_id, path, ref)
    file_row = next((r for r in codeup if r.get("entity_type") == "file" and r.get("repository_id") == repository_id and r.get("path") == path and r.get("ref") == ref and r.get("status") != "deleted"), None)
    if file_row is None:
        _log(token_row, "error", "NOT_FOUND", "File not found at ref")
        return _err("NOT_FOUND", "File not found", repository_id=repository_id, path=path, ref=ref)

    content = file_row.get("content")
    if content is None or content == "":
        # try retrieve via blob store if present
        blob_sha = file_row.get("file_blob_sha")
        if isinstance(blob_sha, str) and blob_sha:
            blobs = _load("git_blobs.json")
            if isinstance(blobs, dict):
                b = blobs.get(blob_sha)
                if isinstance(b, dict):
                    content = b.get("content")
                else:
                    content = None
            elif isinstance(blobs, list):
                b = next((x for x in blobs if isinstance(x, dict) and x.get("sha") == blob_sha), None)
                content = b.get("content") if isinstance(b, dict) else None
        if content is None or content == "":
            _log(token_row, "error", "NOT_FOUND", "File blob content not available")
            return _err("NOT_FOUND", "File blob not available for this ref/path", repository_id=repository_id, path=path, ref=ref, file_blob_sha=file_row.get("file_blob_sha"))

    # update token last_used_at (observable dynamics)
    identities = _load("identity.json")
    if isinstance(identities, list):
        for r in identities:
            if r.get("id") == token_row.get("id"):
                r["last_used_at"] = _now()
                r["updated_at"] = _now()
                break
        _save("identity.json", identities)

    resp = {
        "repository_id": repository_id,
        "path": path,
        "ref": ref,
        "file": file_row,
        "content": content,
        "content_encoding": file_row.get("content_encoding") or "utf-8",
        "file_blob_sha": file_row.get("file_blob_sha"),
    }
    _log(token_row, "ok", None, None)
    return resp

def create_file(repository_id, branch_name, path, content, commit_message, content_encoding=None, author_user_id=None, **_extra):
    import json, os, datetime, re, time, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
