        if not os.path.exists(p):
            _save("request_log.json", [])
        else:
            d = _load("request_log.json")
            if not isinstance(d, list):
                _save("request_log.json", [])

    def _log(token_row, status, error_code=None, message=None, extra=None):
        _ensure_request_log()
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "yunx_req_" + hashlib.sha1(f"{endpoint}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "token_id": token_row.get("id") if isinstance(token_row, dict) else None,
            "organization_id": token_row.get("organization_id") if isinstance(token_row, dict) else None,
            "user_id": token_row.get("user_id") if isinstance(token_row, dict) else None,
            "request": {"repository_id": repository_id, "branch_name": branch_name, "path": path},
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    def _enforce_limits(token_row):
        _ensure_request_log()
        limits = _load("limits.json")
        if not isinstance(limits, dict):
            limits = {}
        rate = limits.get("rate_limit_per_minute", limits.get("per_minute", 240))
        quota = limits.get("quota_per_day", limits.get("per_day", 10000))
        if not isinstance(rate, int) or rate <= 0:
            rate = 240
        if not isinstance(quota, int) or quota <= 0:
            quota = 10000
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        token_id = token_row.get("id") if isinstance(token_row, dict) else None
        per_min = per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if token_id and r.get("token_id") != token_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            d = now - ts
            if d.total_seconds() <= 60:
                per_min += 1
            if d.total_seconds() <= 86400:
                per_day += 1
        if per_min >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit=rate, window_seconds=60)
        if per_day >= quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit=quota, window_seconds=86400)
        return None

    try:
        if not isinstance(repository_id, str) or not re.match(r"^yunx_code_[0-9A-Z]+$", repository_id):
            return _err("VALIDATION_ERROR", "Invalid repository_id", repository_id=repository_id)
        if not isinstance(branch_name, str) or len(branch_name.strip()) < 1:
            return _err("VALIDATION_ERROR", "Invalid branch_name", branch_name=branch_name)
        if not isinstance(path, str) or len(path.strip()) < 1:
            return _err("VALIDATION_ERROR", "Invalid path", path=path)
        if not isinstance(content, str):
            return _err("VALIDATION_ERROR", "Invalid content", content_type=type(content).__name__)
        if not isinstance(commit_message, str) or len(commit_message.strip()) < 1:
            return _err("VALIDATION_ERROR", "Invalid commit_message", commit_message=commit_message)
        if content_encoding is not None and content_encoding not in ("utf-8", "base64"):
            return _err("VALIDATION_ERROR", "Invalid content_encoding", content_encoding=content_encoding)
        if author_user_id is not None and (not isinstance(author_user_id, str) or not re.match(r"^yunx_idn_[0-9A-Z]+$", author_user_id)):
            return _err("VALIDATION_ERROR", "Invalid author_user_id", author_user_id=author_user_id)
    except Exception:
        return _err("VALIDATION_ERROR", "Invalid arguments")

    ident = _load("identity.json")
    if isinstance(ident, dict) and isinstance(ident.get("rows"), list):
        ident_rows = ident["rows"]
        ident_wrapped = True
    elif isinstance(ident, list):
        ident_rows = ident
        ident_wrapped = False
    else:
        ident_rows = []
        ident_wrapped = False

    codeup = _load("codeup.json")
    if isinstance(codeup, dict) and isinstance(codeup.get("rows"), list):
        codeup_rows = codeup["rows"]
        codeup_wrapped = True
    elif isinstance(codeup, list):
        codeup_rows = codeup
        codeup_wrapped = False
    else:
        codeup_rows = []
        codeup_wrapped = False

    # find repository
    repo = None
    for r in codeup_rows:
        if isinstance(r, dict) and r.get("entity_type") == "repository" and r.get("id") == repository_id and r.get("status") != "deleted":
            repo = r
            break
    if repo is None:
        token_row = next((t for t in ident_rows if isinstance(t, dict) and t.get("entity_type") == "api_token" and t.get("status") == "active"), None) or {}
        lim_err = _enforce_limits(token_row)
        if lim_err:
            _log(token_row, "error", lim_err["error"]["code"], lim_err["error"]["message"])
            return lim_err
        _log(token_row, "error", "NOT_FOUND", "Repository not found")
        return _err("NOT_FOUND", "Repository not found", repository_id=repository_id)

    repo_org = repo.get("organization_id")
    token_row = next((t for t in ident_rows if isinstance(t, dict) and t.get("entity_type") == "api_token" and t.get("status") == "active" and t.get("organization_id") == repo_org and t.get("user_id")), None)
    if token_row is None:
        token_row = next((t for t in ident_rows if isinstance(t, dict) and t.get("entity_type") == "api_token" and t.get("status") == "active" and t.get("user_id") and t.get("organization_id")), None)
    if token_row is None:
        lim_err = _enforce_limits({})
        if lim_err:
            _log({}, "error", lim_err["error"]["code"], lim_err["error"]["message"])
            return lim_err
        _log({}, "error", "UNAUTHORIZED", "No active api_token available")
        return _err("UNAUTHORIZED", "No active api_token available")

    lim_err = _enforce_limits(token_row)
    if lim_err:
        _log(token_row, "error", lim_err["error"]["code"], lim_err["error"]["message"])
        return lim_err

    # ensure branch exists
    bn = branch_name.strip()
    branch = next((b for b in codeup_rows if isinstance(b, dict) and b.get("entity_type") == "branch" and b.get("repository_id") == repository_id and b.get("status") != "deleted" and b.get("branch_name") == bn), None)
    if branch is None:
        _log(token_row, "error", "NOT_FOUND", "Branch not found")
        return _err("NOT_FOUND", "Branch not found", repository_id=repository_id, branch_name=bn)

    # decode content for storage/checksum
    enc = content_encoding or "utf-8"
    if enc == "base64":
        try:
            raw = base64.b64decode(content.encode("utf-8"), validate=True)
            stored_content = content  # store as provided
            stored_encoding = "base64"
        except Exception:
            _log(token_row, "error", "VALIDATION_ERROR", "Invalid base64 content")
            return _err("VALIDATION_ERROR", "Invalid base64 content")
    else:
        raw = content.encode("utf-8")
        stored_content = content
        stored_encoding = "utf-8"

    blob_sha = hashlib.sha1(raw).hexdigest()  # stand-in for git blob sha
    commit_sha = hashlib.sha1(f"{repository_id}:{bn}:{path}:{blob_sha}:{commit_message}:{time.time_ns()}".encode("utf-8")).hexdigest()

    now = _now()
    author_id = author_user_id or token_row.get("user_id")

    # create commit row (unique(repository_id, commit_sha))
    if any(isinstance(c, dict) and c.get("entity_type") == "commit" and c.get("repository_id") == repository_id and c.get("commit_sha") == commit_sha for c in codeup_rows):
        # extremely unlikely; regenerate
        commit_sha = hashlib.sha1(f"{commit_sha}:{time.time_ns()}".encode("utf-8")).hexdigest()

    commit_row = {
        "id": _new_id("yunx_code_"),
        "entity_type": "commit",
        "status": "active",
        "organization_id": repo_org,
        "repository_id": repository_id,
        "commit_sha": commit_sha,
        "commit_message": commit_message,
        "author_user_id": author_id,
        "created_at": now,
        "updated_at": now,
    }
    codeup_rows.append(commit_row)

    # file row unique(repository_id, path, ref) among non-deleted.
    # For create_file: conflict if exists and not deleted; if deleted, allow recreate by updating row.
    pth = path.strip()
    ref_val = bn
    file_idx = None
    for i, f in enumerate(codeup_rows):
        if isinstance(f, dict) and f.get("entity_type") == "file" and f.get("repository_id") == repository_id and f.get("path") == pth and f.get("ref") == ref_val:
            file_idx = i
            break

    if file_idx is not None and codeup_rows[file_idx].get("status") != "deleted":
        _log(token_row, "error", "CONFLICT", "File already exists at path/ref")
        return _err("CONFLICT", "File already exists at path/ref", repository_id=repository_id, path=pth, ref=ref_val)

    if file_idx is None:
        file_row = {
            "id": _new_id("yunx_code_"),
            "entity_type": "file",
            "status": "active",
            "organization_id": repo_org,
            "repository_id": repository_id,
            "path": pth,
            "ref": ref_val,
            "file_blob_sha": blob_sha,
            "content": stored_content,
            "content_encoding": stored_encoding,
            "created_at": now,
            "updated_at": now,
        }
        codeup_rows.append(file_row)
    else:
        file_row = codeup_rows[file_idx]
        file_row["status"] = "active"
        file_row["file_blob_sha"] = blob_sha
        file_row["content"] = stored_content
        file_row["content_encoding"] = stored_encoding
        file_row["updated_at"] = now
        if not file_row.get("created_at"):
            file_row["created_at"] = now
        codeup_rows[file_idx] = file_row

    # update branch head to this commit
    for i, b in enumerate(codeup_rows):
        if isinstance(b, dict) and b.get("entity_type") == "branch" and b.get("repository_id") == repository_id and b.get("branch_name") == bn and b.get("status") != "deleted":
            b["head_commit_id"] = commit_row["id"]
            b["updated_at"] = now
            codeup_rows[i] = b
            break

    if codeup_wrapped:
        codeup["rows"] = codeup_rows
        _save("codeup.json", codeup)
    else:
        _save("codeup.json", codeup_rows)

    token_row["last_used_at"] = now
    for i, r in enumerate(ident_rows):
        if isinstance(r, dict) and r.get("id") == token_row.get("id"):
            ident_rows[i] = token_row
            break
    if ident_wrapped:
        ident["rows"] = ident_rows
        _save("identity.json", ident)
    else:
        _save("identity.json", ident_rows)

    _log(token_row, "ok", extra={"file_id": file_row["id"], "commit_id": commit_row["id"]})
    return {"file": file_row, "commit": commit_row}

def update_file(repository_id, branch_name, path, content, commit_message, content_encoding=None, author_user_id=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, endpoint, token_id=None, org_id=None, user_id=None, error_code=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "yunx_req_" + hashlib.sha1((endpoint + "|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:16].upper(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "token_id": token_id,
            "organization_id": org_id,
            "user_id": user_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        logs.append(row)
        _save("request_log.json", logs)

    def _rate_limit_check(token_id):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            return None
        window_sec = 60
        limit = 60
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_sec)
        cnt = 0
        for r in logs:
            if r.get("token_id") != token_id:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_sec, limit=limit)
        return None

    # Validate inputs
    if not isinstance(repository_id, str) or not re.match(r"^yunx_code_[0-9A-Z]+$", repository_id):
        _log("error", "update_file", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid repository_id")
    if not isinstance(branch_name, str) or len(branch_name) < 1:
        _log("error", "update_file", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid branch_name")
    if not isinstance(path, str) or len(path) < 1:
        _log("error", "update_file", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid path")
    if not isinstance(content, str):
        _log("error", "update_file", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid content")
    if not isinstance(commit_message, str) or len(commit_message) < 1:
        _log("error", "update_file", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid commit_message")
    if content_encoding is not None and content_encoding not in ("utf-8", "base64"):
        _log("error", "update_file", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid content_encoding")
    if author_user_id is not None and (not isinstance(author_user_id, str) or not re.match(r"^yunx_idn_[0-9A-Z]+$", author_user_id)):
        _log("error", "update_file", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid author_user_id")

    identity = _load("identity.json")
    codeup = _load("codeup.json")

    # Find repository
    repo = None
    for r in codeup:
        if isinstance(r, dict) and r.get("entity_type") == "repository" and r.get("id") == repository_id and r.get("status") != "deleted":
            repo = r
            break
    if repo is None:
        _log("error", "update_file", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Repository not found")

    # Ambient auth token in same org
    tokens = [r for r in identity if isinstance(r, dict) and r.get("entity_type") == "api_token" and r.get("status") == "active" and r.get("organization_id") == repo.get("organization_id") and r.get("user_id")]
    if not tokens:
        _log("error", "update_file", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active token authorized for this repository")
    token = tokens[0]

    rl = _rate_limit_check(token.get("id"))
    if rl:
        _log("error", "update_file", token_id=token.get("id"), org_id=token.get("organization_id"), user_id=token.get("user_id"), error_code=rl["error"]["code"])
        return rl

    # Validate author
    author_id = author_user_id or token.get("user_id")
    author_user = None
    for r in identity:
        if isinstance(r, dict) and r.get("id") == author_id and r.get("entity_type") == "user" and r.get("status") == "active":
            author_user = r
            break
    if author_user is None:
        _log("error", "update_file", token_id=token.get("id"), org_id=token.get("organization_id"), user_id=token.get("user_id"), error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "author_user_id does not reference an active user")
    is_member = False
    for r in identity:
        if isinstance(r, dict) and r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("organization_id") == repo.get("organization_id") and r.get("user_id") == author_id:
            is_member = True
            break
    if not is_member:
        _log("error", "update_file", token_id=token.get("id"), org_id=token.get("organization_id"), user_id=token.get("user_id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "author_user_id is not an active member of the organization")

    # Branch exists
    branch = None
    for r in codeup:
        if isinstance(r, dict) and r.get("entity_type") == "branch" and r.get("repository_id") == repository_id and r.get("branch_name") == branch_name and r.get("status") != "deleted":
            branch = r
            break
    if branch is None:
        _log("error", "update_file", token_id=token.get("id"), org_id=token.get("organization_id"), user_id=token.get("user_id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Branch not found")

    # File must exist
    file_idx = None
    for i, r in enumerate(codeup):
        if isinstance(r, dict) and r.get("entity_type") == "file" and r.get("repository_id") == repository_id and r.get("path") == path and r.get("ref") == branch_name and r.get("status") != "deleted":
            file_idx = i
            break
    if file_idx is None:
        _log("error", "update_file", token_id=token.get("id"), org_id=token.get("organization_id"), user_id=token.get("user_id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "File not found at given path on branch")

    # Create new commit row
    commit_sha = hashlib.sha1((repository_id + "|" + branch_name + "|" + path + "|" + now + "|" + commit_message).encode("utf-8")).hexdigest()
    for r in codeup:
        if isinstance(r, dict) and r.get("entity_type") == "commit" and r.get("repository_id") == repository_id and r.get("commit_sha") == commit_sha:
            commit_sha = hashlib.sha1((commit_sha + "|" + str(time.time())).encode("utf-8")).hexdigest()
            break

    def _new_id(prefix):
        return prefix + hashlib.sha1((prefix + "|" + now + "|" + str(time.time())).encode("utf-8")).hexdigest()[:16].upper()

    commit_id = _new_id("yunx_code_")
    commit_row = {
        "id": commit_id,
        "entity_type": "commit",
        "status": "active",
        "organization_id": repo.get("organization_id"),
        "repository_id": repository_id,
        "commit_sha": commit_sha,
        "commit_message": commit_message,
        "author_user_id": author_id,
        "created_at": now,
        "updated_at": now,
    }

    # Update file row content and sha
    enc = content_encoding or (codeup[file_idx].get("content_encoding") or "utf-8")
    blob_sha = hashlib.sha256((enc + ":" + content).encode("utf-8")).hexdigest()
    codeup[file_idx]["content"] = content
    codeup[file_idx]["content_encoding"] = enc
    codeup[file_idx]["file_blob_sha"] = blob_sha
    codeup[file_idx]["updated_at"] = now
    # Ensure updated_at >= created_at (string compare not reliable; just set)
    if not codeup[file_idx].get("created_at"):
        codeup[file_idx]["created_at"] = now

    # Persist commit and branch head
    codeup.append(commit_row)
    for r in codeup:
        if isinstance(r, dict) and r.get("id") == branch.get("id"):
            r["head_commit_id"] = commit_id
            r["updated_at"] = now
            break
    _save("codeup.json", codeup)

    # Update token last_used_at
    for r in identity:
        if isinstance(r, dict) and r.get("id") == token.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now if r.get("updated_at", now) <= now else r.get("updated_at")
            break
    _save("identity.json", identity)

    _log("ok", "update_file", token_id=token.get("id"), org_id=token.get("organization_id"), user_id=token.get("user_id"))
    return {
        "repository_id": repository_id,
        "branch_name": branch_name,
        "path": path,
        "file": codeup[file_idx],
        "commit": commit_row,
    }

def delete_file(repository_id, branch_name, path, commit_message, author_user_id=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_file"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return prefix + hashlib.sha1(f"{prefix}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:18].upper()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _ensure_request_log():
        p = os.path.join(_DB, "request_log.json")
        if not os.path.exists(p):
            _save("request_log.json", [])
        else:
            d = _load("request_log.json")
            if not isinstance(d, list):
                _save("request_log.json", [])

    def _log(token_row, status, error_code=None, message=None, extra=None):
        _ensure_request_log()
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "yunx_req_" + hashlib.sha1(f"{endpoint}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "token_id": token_row.get("id") if isinstance(token_row, dict) else None,
            "organization_id": token_row.get("organization_id") if isinstance(token_row, dict) else None,
            "user_id": token_row.get("user_id") if isinstance(token_row, dict) else None,
            "request": {"repository_id": repository_id, "branch_name": branch_name, "path": path},
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    def _enforce_limits(token_row):
        _ensure_request_log()
        limits = _load("limits.json")
        if not isinstance(limits, dict):
            limits = {}
        rate = limits.get("rate_limit_per_minute", limits.get("per_minute", 240))
        quota = limits.get("quota_per_day", limits.get("per_day", 10000))
        if not isinstance(rate, int) or rate <= 0:
            rate = 240
        if not isinstance(quota, int) or quota <= 0:
            quota = 10000
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        token_id = token_row.get("id") if isinstance(token_row, dict) else None
        per_min = per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if token_id and r.get("token_id") != token_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            d = now - ts
            if d.total_seconds() <= 60:
                per_min += 1
            if d.total_seconds() <= 86400:
                per_day += 1
        if per_min >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit=rate, window_seconds=60)
        if per_day >= quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit=quota, window_seconds=86400)
        return None

    try:
        if not isinstance(repository_id, str) or not re.match(r"^yunx_code_[0-9A-Z]+$", repository_id):
            return _err("VALIDATION_ERROR", "Invalid repository_id", repository_id=repository_id)
        if not isinstance(branch_name, str) or len(branch_name.strip()) < 1:
            return _err("VALIDATION_ERROR", "Invalid branch_name", branch_name=branch_name)
        if not isinstance(path, str) or len(path.strip()) < 1:
            return _err("VALIDATION_ERROR", "Invalid path", path=path)
        if not isinstance(commit_message, str) or len(commit_message.strip()) < 1:
            return _err("VALIDATION_ERROR", "Invalid commit_message", commit_message=commit_message)
        if author_user_id is not None and (not isinstance(author_user_id, str) or not re.match(r"^yunx_idn_[0-9A-Z]+$", author_user_id)):
            return _err("VALIDATION_ERROR", "Invalid author_user_id", author_user_id=author_user_id)
    except Exception:
        return _err("VALIDATION_ERROR", "Invalid arguments")

    ident = _load("identity.json")
    if isinstance(ident, dict) and isinstance(ident.get("rows"), list):
        ident_rows = ident["rows"]
        ident_wrapped = True
    elif isinstance(ident, list):
        ident_rows = ident
        ident_wrapped = False
    else:
        ident_rows = []
        ident_wrapped = False

    codeup = _load("codeup.json")
    if isinstance(codeup, dict) and isinstance(codeup.get("rows"), list):
        codeup_rows = codeup["rows"]
        codeup_wrapped = True
    elif isinstance(codeup, list):
        codeup_rows = codeup
        codeup_wrapped = False
    else:
        codeup_rows = []
        codeup_wrapped = False

    repo = next((r for r in codeup_rows if isinstance(r, dict) and r.get("entity_type") == "repository" and r.get("id") == repository_id and r.get("status") != "deleted"), None)
    if repo is None:
        token_row = next((t for t in ident_rows if isinstance(t, dict) and t.get("entity_type") == "api_token" and t.get("status") == "active"), None) or {}
        lim_err = _enforce_limits(token_row)
        if lim_err:
            _log(token_row, "error", lim_err["error"]["code"], lim_err["error"]["message"])
            return lim_err
        _log(token_row, "error", "NOT_FOUND", "Repository not found")
        return _err("NOT_FOUND", "Repository not found", repository_id=repository_id)

    repo_org = repo.get("organization_id")
    token_row = next((t for t in ident_rows if isinstance(t, dict) and t.get("entity_type") == "api_token" and t.get("status") == "active" and t.get("organization_id") == repo_org and t.get("user_id")), None)
    if token_row is None:
        token_row = next((t for t in ident_rows if isinstance(t, dict) and t.get("entity_type") == "api_token" and t.get("status") == "active" and t.get("user_id") and t.get("organization_id")), None)
    if token_row is None:
        lim_err = _enforce_limits({})
        if lim_err:
            _log({}, "error", lim_err["error"]["code"], lim_err["error"]["message"])
            return lim_err
        _log({}, "error", "UNAUTHORIZED", "No active api_token available")
        return _err("UNAUTHORIZED", "No active api_token available")

    lim_err = _enforce_limits(token_row)
    if lim_err:
        _log(token_row, "error", lim_err["error"]["code"], lim_err["error"]["message"])
        return lim_err

    bn = branch_name.strip()
    branch = next((b for b in codeup_rows if isinstance(b, dict) and b.get("entity_type") == "branch" and b.get("repository_id") == repository_id and b.get("status") != "deleted" and b.get("branch_name") == bn), None)
    if branch is None:
        _log(token_row, "error", "NOT_FOUND", "Branch not found")
        return _err("NOT_FOUND", "Branch not found", repository_id=repository_id, branch_name=bn)

    pth = path.strip()
    ref_val = bn
    file_idx = None
    for i, f in enumerate(codeup_rows):
        if isinstance(f, dict) and f.get("entity_type") == "file" and f.get("repository_id") == repository_id and f.get("path") == pth and f.get("ref") == ref_val:
            file_idx = i
            break
    if file_idx is None or codeup_rows[file_idx].get("status") == "deleted":
        _log(token_row, "error", "NOT_FOUND", "File not found at path/ref")
        return _err("NOT_FOUND", "File not found at path/ref", repository_id=repository_id, path=pth, ref=ref_val)

    now = _now()
    author_id = author_user_id or token_row.get("user_id")
    commit_sha = hashlib.sha1(f"delete:{repository_id}:{bn}:{pth}:{commit_message}:{time.time_ns()}".encode("utf-8")).hexdigest()
    if any(isinstance(c, dict) and c.get("entity_type") == "commit" and c.get("repository_id") == repository_id and c.get("commit_sha") == commit_sha for c in codeup_rows):
        commit_sha = hashlib.sha1(f"{commit_sha}:{time.time_ns()}".encode("utf-8")).hexdigest()

    commit_row = {
        "id": _new_id("yunx_code_"),
        "entity_type": "commit",
        "status": "active",
        "organization_id": repo_org,
        "repository_id": repository_id,
        "commit_sha": commit_sha,
        "commit_message": commit_message,
        "author_user_id": author_id,
        "created_at": now,
        "updated_at": now,
    }
    codeup_rows.append(commit_row)

    file_row = codeup_rows[file_idx]
    file_row["status"] = "deleted"
    file_row["updated_at"] = now
    codeup_rows[file_idx] = file_row

    # update branch head
    for i, b in enumerate(codeup_rows):
        if isinstance(b, dict) and b.get("entity_type") == "branch" and b.get("repository_id") == repository_id and b.get("branch_name") == bn and b.get("status") != "deleted":
            b["head_commit_id"] = commit_row["id"]
            b["updated_at"] = now
            codeup_rows[i] = b
            break

    if codeup_wrapped:
        codeup["rows"] = codeup_rows
        _save("codeup.json", codeup)
    else:
        _save("codeup.json", codeup_rows)

    token_row["last_used_at"] = now
    for i, r in enumerate(ident_rows):
        if isinstance(r, dict) and r.get("id") == token_row.get("id"):
            ident_rows[i] = token_row
            break
    if ident_wrapped:
        ident["rows"] = ident_rows
        _save("identity.json", ident)
    else:
        _save("identity.json", ident_rows)

    _log(token_row, "ok", extra={"file_id": file_row.get("id"), "commit_id": commit_row["id"]})
    return {"file": file_row, "commit": commit_row}

def compare(repositoryId, sourceRef, targetRef, path=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "compare"
    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _ensure_request_log():
        p = os.path.join(_DB, "request_log.json")
        if not os.path.exists(p):
            _save("request_log.json", [])
            return []
        d = _load("request_log.json")
        if not isinstance(d, list):
            _save("request_log.json", [])
            return []
        return d

    def _log(token_row, status, error_code=None, message=None, extra=None):
        logs = _ensure_request_log()
        row = {
            "id": "yunx_req_" + hashlib.sha1(f"{endpoint}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "token_id": token_row.get("id") if isinstance(token_row, dict) else None,
            "organization_id": token_row.get("organization_id") if isinstance(token_row, dict) else None,
            "user_id": token_row.get("user_id") if isinstance(token_row, dict) else None,
            "request": {"repositoryId": repositoryId, "sourceRef": sourceRef, "targetRef": targetRef, "path": path},
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    def _resolve_token_context():
        identities = _load("identity.json")
        if not isinstance(identities, list):
            identities = []
        for tok in identities:
            if tok.get("entity_type") != "api_token" or tok.get("status") != "active":
                continue
            uid = tok.get("user_id")
            oid = tok.get("organization_id")
            if not isinstance(uid, str) or not uid or not isinstance(oid, str) or not oid:
                continue
            u = next((r for r in identities if r.get("id") == uid and r.get("entity_type") == "user" and r.get("status") == "active"), None)
            o = next((r for r in identities if r.get("id") == oid and r.get("entity_type") == "organization" and r.get("status") == "active"), None)
            if not u or not o:
                continue
            m = next((r for r in identities if r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("user_id") == uid and r.get("organization_id") == oid), None)
            if not m:
                continue
            exp = tok.get("expires_at")
            if isinstance(exp, str) and exp:
                exp_dt = _parse_dt(exp)
                if exp_dt is not None and exp_dt <= datetime.datetime.utcnow():
                    continue
            return tok, u, o
        return None, None, None

    def _rate_limit_check(token_row):
        if not isinstance(token_row, dict):
            return None
        logs = _ensure_request_log()
        token_id = token_row.get("id")
        if not isinstance(token_id, str) or not token_id:
            return None
        window_sec = 60
        limit = 120
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_sec)
        cnt = 0
        for r in reversed(logs[-5000:]):
            if r.get("token_id") != token_id:
                continue
            dt = _parse_dt(r.get("timestamp"))
            if not dt:
                continue
            if dt >= cutoff:
                cnt += 1
                if cnt >= limit:
                    return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_sec, limit=limit)
        return None

    # Validate
    if not isinstance(repositoryId, str) or re.match(r"^yunx_code_01J[0-9A-Z]+$", repositoryId) is None:
        tok, _, _ = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid repositoryId", {"repositoryId": repositoryId})
        return _err("VALIDATION_ERROR", "Invalid repositoryId", repositoryId=repositoryId)
    if not isinstance(sourceRef, str) or not sourceRef:
        tok, _, _ = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid sourceRef")
        return _err("VALIDATION_ERROR", "Invalid sourceRef", sourceRef=sourceRef)
    if not isinstance(targetRef, str) or not targetRef:
        tok, _, _ = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid targetRef")
        return _err("VALIDATION_ERROR", "Invalid targetRef", targetRef=targetRef)
    if path is not None and (not isinstance(path, str) or not path):
        tok, _, _ = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid path")
        return _err("VALIDATION_ERROR", "Invalid path", path=path)

    token_row, _, _ = _resolve_token_context()
    if token_row is None:
        _log(None, "error", "UNAUTHORIZED", "Token is missing or invalid")
        return _err("UNAUTHORIZED", "Token is missing or invalid")
    rl = _rate_limit_check(token_row)
    if rl:
        _log(token_row, "error", "RATE_LIMIT", rl["error"]["message"])
        return rl

    codeup = _load("codeup.json")
    if not isinstance(codeup, list):
        codeup = []
    repo = next((r for r in codeup if r.get("entity_type") == "repository" and r.get("id") == repositoryId and r.get("status") != "deleted"), None)
    if repo is None:
        _log(token_row, "error", "NOT_FOUND", "Repository not found")
        return _err("NOT_FOUND", "Repository not found", repositoryId=repositoryId)
    if repo.get("organization_id") != token_row.get("organization_id"):
        _log(token_row, "error", "UNAUTHORIZED", "Token not authorized for this repository")
        return _err("UNAUTHORIZED", "No active token authorized for this repository")

    # Compare: for this datastore-backed implementation, compute diff_summary using file rows at the two refs.
    files = [r for r in codeup if r.get("entity_type") == "file" and r.get("repository_id") == repositoryId and r.get("status") != "deleted"]
    if path:
        if path.endswith("/"):
            files = [r for r in files if isinstance(r.get("path"), str) and r.get("path").startswith(path)]
        else:
            files = [r for r in files if r.get("path") == path]

    src_files = {}
    tgt_files = {}
    for r in files:
        if r.get("ref") == sourceRef:
            src_files[r.get("path")] = r
        if r.get("ref") == targetRef:
            tgt_files[r.get("path")] = r

    if not src_files and not tgt_files:
        # if neither ref has any file entries, treat as ref not found
        _log(token_row, "error", "NOT_FOUND", "Ref(s) could not be resolved")
        return _err("NOT_FOUND", "One or both refs cannot be resolved in this repository", repositoryId=repositoryId, sourceRef=sourceRef, targetRef=targetRef)

    all_paths = set([p for p in src_files.keys() if isinstance(p, str)] + [p for p in tgt_files.keys() if isinstance(p, str)])
    added = 0
    deleted = 0
    modified = 0
    changes = []

    for pth in sorted(all_paths):
        s = src_files.get(pth)
        t = tgt_files.get(pth)
        if s is None and t is not None:
            added += 1
            changes.append({"path": pth, "type": "added"})
            continue
        if s is not None and t is None:
            deleted += 1
            changes.append({"path": pth, "type": "deleted"})
            continue
        # both exist
        s_sha = s.get("file_blob_sha") or hashlib.sha1((s.get("content") or "").encode("utf-8", "ignore")).hexdigest()
        t_sha = t.get("file_blob_sha") or hashlib.sha1((t.get("content") or "").encode("utf-8", "ignore")).hexdigest()
        if s_sha != t_sha:
            modified += 1
            changes.append({"path": pth, "type": "modified", "source_blob": s.get("file_blob_sha"), "target_blob": t.get("file_blob_sha")})

    diff_summary = {"files_changed": added + deleted + modified, "added": added, "deleted": deleted, "modified": modified}
    result = {
        "repositoryId": repositoryId,
        "sourceRef": sourceRef,
        "targetRef": targetRef,
        "path": path,
        "diff_summary": diff_summary,
        "changes": changes,
    }

    identities = _load("identity.json")
    if isinstance(identities, list):
        for r in identities:
            if r.get("id") == token_row.get("id"):
                r["last_used_at"] = _now()
                r["updated_at"] = _now()
                break
        _save("identity.json", identities)

    _log(token_row, "ok")
    return result

def get_repository(repositoryId, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_repository"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log_request(token_row, status_code, error_code=None, message=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "yunx_req_" + hashlib.sha256(f"{endpoint}|{_now()}|{os.getpid()}|{time.time()}".encode("utf-8")).hexdigest()[:18].upper(),
            "endpoint": endpoint,
            "token_id": token_row.get("id") if token_row else None,
            "organization_id": token_row.get("organization_id") if token_row else None,
            "user_id": token_row.get("user_id") if token_row else None,
            "status": status_code,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now(),
        }
        logs.append(row)
        _save("request_log.json", logs)

    def _enforce_limits(token_row):
        limits = _load("limits.json")
        if not isinstance(limits, dict):
            limits = {}
        rate = limits.get("rate_limit_per_minute", 120)
        quota = limits.get("quota_per_day", 5000)

        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        win_start = now - datetime.timedelta(minutes=1)
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

        token_id = token_row.get("id")
        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("token_id") != token_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if not dt:
                continue
            if dt >= win_start:
                per_min += 1
            if dt >= day_start:
                per_day += 1
        if isinstance(rate, int) and rate >= 0 and per_min >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(quota, int) and quota >= 0 and per_day >= quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _resolve_token():
        identities = _load("identity.json")
        if not isinstance(identities, list):
            identities = []
        now = datetime.datetime.utcnow()
        for row in identities:
            if not isinstance(row, dict):
                continue
            if row.get("entity_type") != "api_token" or row.get("status") != "active":
                continue
            if not row.get("organization_id") or not row.get("user_id"):
                continue
            exp = _parse_dt(row.get("expires_at"))
            if exp and exp <= now:
                continue
            return row
        return None

    token = _resolve_token()
    if not token:
        _log_request(None, 401, "UNAUTHORIZED", "No active api_token available.")
        return _err("UNAUTHORIZED", "No active api_token available.")

    lim_err = _enforce_limits(token)
    if lim_err:
        _log_request(token, 429, lim_err["error"]["code"], lim_err["error"]["message"])
        return lim_err

    if not isinstance(repositoryId, str) or not re.match(r"^yunx_code_01J[0-9A-Z]+$", repositoryId):
        _log_request(token, 400, "VALIDATION_ERROR", "Invalid repositoryId.")
        return _err("VALIDATION_ERROR", "Invalid repositoryId.")

    identities = _load("identity.json")
    if not isinstance(identities, list):
        identities = []
    org_id = token.get("organization_id")
    org = next((r for r in identities if isinstance(r, dict) and r.get("id") == org_id and r.get("entity_type") == "organization" and r.get("status") == "active"), None)
    if not org:
        _log_request(token, 401, "UNAUTHORIZED", "Authorized organization is not available.")
        return _err("UNAUTHORIZED", "Authorized organization is not available.")

    codeup = _load("codeup.json")
    if not isinstance(codeup, list):
        codeup = []
    repo = next((r for r in codeup if isinstance(r, dict) and r.get("id") == repositoryId and r.get("entity_type") == "repository" and r.get("organization_id") == org_id and r.get("status") != "deleted"), None)
    if not repo:
        _log_request(token, 404, "NOT_FOUND", "Repository not found.")
        return _err("NOT_FOUND", "Repository not found.")

    # Update token last_used_at
    for r in identities:
        if isinstance(r, dict) and r.get("id") == token.get("id"):
            r["last_used_at"] = _now()
            r["updated_at"] = _now()
            break
    _save("identity.json", identities)

    _log_request(token, 200)
    return {"repository": repo}

