        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        win_start = now - datetime.timedelta(minutes=1)
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

        token_id = token_row.get("id")
        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("token_id") != token_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if not dt:
                continue
            if dt >= win_start:
                per_min += 1
            if dt >= day_start:
                per_day += 1
        if isinstance(rate, int) and rate >= 0 and per_min >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(quota, int) and quota >= 0 and per_day >= quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _resolve_token():
        identities = _load("identity.json")
        if not isinstance(identities, list):
            identities = []
        now = datetime.datetime.utcnow()
        for row in identities:
            if not isinstance(row, dict):
                continue
            if row.get("entity_type") != "api_token" or row.get("status") != "active":
                continue
            if not row.get("organization_id") or not row.get("user_id"):
                continue
            exp = _parse_dt(row.get("expires_at"))
            if exp and exp <= now:
                continue
            return row
        return None

    token = _resolve_token()
    if not token:
        _log_request(None, 401, "UNAUTHORIZED", "No active api_token available.")
        return _err("UNAUTHORIZED", "No active api_token available.")

    lim_err = _enforce_limits(token)
    if lim_err:
        _log_request(token, 429, lim_err["error"]["code"], lim_err["error"]["message"])
        return lim_err

    # Validate inputs
    if not isinstance(organizationId, str) or not re.match(r"^yunx_idn_01J[0-9A-Z]+$", organizationId):
        _log_request(token, 400, "VALIDATION_ERROR", "Invalid organizationId.")
        return _err("VALIDATION_ERROR", "Invalid organizationId.")
    if projectId is not None and (not isinstance(projectId, str) or not re.match(r"^yunx_prj_01J[0-9A-Z]+$", projectId)):
        _log_request(token, 400, "VALIDATION_ERROR", "Invalid projectId.")
        return _err("VALIDATION_ERROR", "Invalid projectId.")
    if status is not None and status not in ("active", "archived", "deleted"):
        _log_request(token, 400, "VALIDATION_ERROR", "Invalid status.")
        return _err("VALIDATION_ERROR", "Invalid status.")
    if search is not None and not isinstance(search, str):
        _log_request(token, 400, "VALIDATION_ERROR", "search must be a string.")
        return _err("VALIDATION_ERROR", "search must be a string.")
    if sortBy is not None and sortBy not in ("created_at", "updated_at", "name"):
        _log_request(token, 400, "VALIDATION_ERROR", "Invalid sortBy.")
        return _err("VALIDATION_ERROR", "Invalid sortBy.")
    if sortOrder is not None and sortOrder not in ("asc", "desc"):
        _log_request(token, 400, "VALIDATION_ERROR", "Invalid sortOrder.")
        return _err("VALIDATION_ERROR", "Invalid sortOrder.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log_request(token, 400, "VALIDATION_ERROR", "limit out of range.")
        return _err("VALIDATION_ERROR", "limit out of range.")
    if cursor is not None and not isinstance(cursor, str):
        _log_request(token, 400, "VALIDATION_ERROR", "cursor must be a string.")
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    # Authorization: token org takes precedence; must match requested org for this surface
    if token.get("organization_id") != organizationId:
        _log_request(token, 401, "UNAUTHORIZED", "Token is not authorized for requested organization.")
        return _err("UNAUTHORIZED", "Token is not authorized for requested organization.")

    identities = _load("identity.json")
    if not isinstance(identities, list):
        identities = []
    org = next((r for r in identities if isinstance(r, dict) and r.get("id") == organizationId and r.get("entity_type") == "organization" and r.get("status") == "active"), None)
    if not org:
        _log_request(token, 404, "NOT_FOUND", "Organization not found.")
        return _err("NOT_FOUND", "Organization not found.")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    if projectId is not None:
        pr = next((r for r in projects if isinstance(r, dict) and r.get("id") == projectId and r.get("entity_type") == "project" and r.get("organization_id") == organizationId and r.get("status") != "deleted"), None)
        if not pr:
            _log_request(token, 404, "NOT_FOUND", "Project not found.")
            return _err("NOT_FOUND", "Project not found.")

    codeup = _load("codeup.json")
    if not isinstance(codeup, list):
        codeup = []
    rows = []
    for r in codeup:
        if not isinstance(r, dict):
            continue
        if r.get("entity_type") != "repository":
            continue
        if r.get("organization_id") != organizationId:
            continue
        if status is not None:
            if r.get("status") != status:
                continue
        else:
            if r.get("status") == "deleted":
                continue
        if projectId is not None and r.get("project_id") != projectId:
            continue
        if search is not None and search.strip():
            nm = (r.get("name") or "")
            if search.strip().lower() not in nm.lower():
                continue
        rows.append(r)

    sort_key = sortBy or "created_at"
    rev = (sortOrder or "desc") == "desc"

    def _sort_val(r):
        if sort_key in ("created_at", "updated_at"):
            dt = _parse_dt(r.get(sort_key))
            return dt or datetime.datetime.min
        if sort_key == "name":
            return (r.get("name") or "").lower()
        return r.get("id") or ""

    rows.sort(key=_sort_val, reverse=rev)

    # Cursor: base64 encoded integer offset
    offset = 0
    if cursor:
        try:
            offset = int(base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8"))
            if offset < 0:
                offset = 0
        except Exception:
            _log_request(token, 400, "VALIDATION_ERROR", "Invalid cursor.")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    # Update token last_used_at
    for r in identities:
        if isinstance(r, dict) and r.get("id") == token.get("id"):
            r["last_used_at"] = _now()
            r["updated_at"] = _now()
            break
    _save("identity.json", identities)

    _log_request(token, 200)
    return {
        "items": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort_by": sort_key,
        "sort_order": "desc" if rev else "asc",
    }

def get_change_request(changeRequestId, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_change_request"
    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _ensure_request_log():
        p = os.path.join(_DB, "request_log.json")
        if not os.path.exists(p):
            _save("request_log.json", [])
            return []
        d = _load("request_log.json")
        if not isinstance(d, list):
            _save("request_log.json", [])
            return []
        return d

    def _log(token_row, status, error_code=None, message=None, extra=None):
        logs = _ensure_request_log()
        row = {
            "id": "yunx_req_" + hashlib.sha1(f"{endpoint}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "token_id": token_row.get("id") if isinstance(token_row, dict) else None,
            "organization_id": token_row.get("organization_id") if isinstance(token_row, dict) else None,
            "user_id": token_row.get("user_id") if isinstance(token_row, dict) else None,
            "request": {"changeRequestId": changeRequestId},
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    def _resolve_token_context():
        identities = _load("identity.json")
        if not isinstance(identities, list):
            identities = []
        for tok in identities:
            if tok.get("entity_type") != "api_token" or tok.get("status") != "active":
                continue
            uid = tok.get("user_id")
            oid = tok.get("organization_id")
            if not isinstance(uid, str) or not uid or not isinstance(oid, str) or not oid:
                continue
            u = next((r for r in identities if r.get("id") == uid and r.get("entity_type") == "user" and r.get("status") == "active"), None)
            o = next((r for r in identities if r.get("id") == oid and r.get("entity_type") == "organization" and r.get("status") == "active"), None)
            if not u or not o:
                continue
            m = next((r for r in identities if r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("user_id") == uid and r.get("organization_id") == oid), None)
            if not m:
                continue
            exp = tok.get("expires_at")
            if isinstance(exp, str) and exp:
                exp_dt = _parse_dt(exp)
                if exp_dt is not None and exp_dt <= datetime.datetime.utcnow():
                    continue
            return tok
        return None

    if not isinstance(changeRequestId, str) or re.match(r"^yunx_code_01J[0-9A-Z]+$", changeRequestId) is None:
        tok = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid changeRequestId")
        return _err("VALIDATION_ERROR", "Invalid changeRequestId", changeRequestId=changeRequestId)

    token_row = _resolve_token_context()
    if token_row is None:
        _log(None, "error", "UNAUTHORIZED", "Token is missing or invalid")
        return _err("UNAUTHORIZED", "Token is missing or invalid")

    codeup = _load("codeup.json")
    if not isinstance(codeup, list):
        codeup = []

    cr = next((r for r in codeup if r.get("entity_type") == "change_request" and r.get("id") == changeRequestId and r.get("status") != "deleted"), None)
    if cr is None:
        _log(token_row, "error", "NOT_FOUND", "Change request not found")
        return _err("NOT_FOUND", "Change request not found", changeRequestId=changeRequestId)

    if cr.get("organization_id") != token_row.get("organization_id"):
        _log(token_row, "error", "UNAUTHORIZED", "Token not authorized for this change request")
        return _err("UNAUTHORIZED", "Token is not permitted to read change requests in this organization")

    # include comments + patch sets
    comments = [r for r in codeup if r.get("entity_type") == "change_request_comment" and r.get("change_request_id") == changeRequestId and r.get("status") != "deleted"]
    comments.sort(key=lambda r: r.get("created_at") or "")
    patch_sets = [r for r in codeup if r.get("entity_type") == "patch_set" and r.get("change_request_id") == changeRequestId and r.get("status") != "deleted"]
    patch_sets.sort(key=lambda r: (r.get("patch_set_number") if isinstance(r.get("patch_set_number"), int) else 10**9, r.get("created_at") or ""))

    identities = _load("identity.json")
    if isinstance(identities, list):
        for r in identities:
            if r.get("id") == token_row.get("id"):
                r["last_used_at"] = _now()
                r["updated_at"] = _now()
                break
        _save("identity.json", identities)

    _log(token_row, "ok")
    return {"change_request": cr, "comments": comments, "patch_sets": patch_sets}

def list_change_requests(organizationId, repositoryId, status=None, sourceBranch=None, targetBranch=None, authorUserId=None, reviewerUserId=None, sortBy=None, sortOrder=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_change_requests"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_str(x):
        return isinstance(x, str)

    def _validate_pattern(val, pat, field):
        if not _is_str(val) or not re.match(pat, val):
            return _err("VALIDATION_ERROR", f"Invalid {field}.", field=field)
        return None

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not _is_str(cur) or not cur:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            return obj
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    def _encode_cursor(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # ---- Authorization (ambient): must be backed by an active api_token in store ----
    identity = _load("identity.json")
    tokens = [r for r in identity if isinstance(r, dict) and r.get("entity_type") == "api_token" and r.get("status") == "active" and r.get("user_id") and r.get("organization_id")]
    token_row = tokens[0] if tokens else None

    # ---- Rate limiting / quota via request log (identity rows with entity_type='request_log') ----
    # Not declared in schema; if present, use it.
    reqlog_file = "request_log.json"
    reqlog = _load(reqlog_file)
    if not isinstance(reqlog, list):
        reqlog = []

    def _log(status_code, message=None, used_token_id=None, extra=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "yunx_req_" + hashlib.sha1(f"{endpoint}:{_now()}:{latency_ms}:{os.getpid()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status_code,
            "latency_ms": latency_ms,
            "token_id": used_token_id,
        }
        if message:
            row["message"] = message
        if isinstance(extra, dict):
            row.update(extra)
        reqlog.append(row)
        try:
            _save(reqlog_file, reqlog)
        except Exception:
            # do not fail the API call for logging issues
            pass

    if token_row is None:
        _log("UNAUTHORIZED", "No active api_token available to authorize request.", None)
        return _err("UNAUTHORIZED", "No active API token available.")

    # ---- Validate inputs ----
    e = _validate_pattern(organizationId, r"^yunx_idn_01J[0-9A-Z]+$", "organizationId")
    if e:
        _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
        return e
    e = _validate_pattern(repositoryId, r"^yunx_code_01J[0-9A-Z]+$", "repositoryId")
    if e:
        _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
        return e

    if status is not None:
        if not _is_str(status) or status not in ("open", "merged", "closed"):
            e = _err("VALIDATION_ERROR", "Invalid status.", field="status")
            _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
            return e
    if sourceBranch is not None and not _is_str(sourceBranch):
        e = _err("VALIDATION_ERROR", "Invalid sourceBranch.", field="sourceBranch")
        _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
        return e
    if targetBranch is not None and not _is_str(targetBranch):
        e = _err("VALIDATION_ERROR", "Invalid targetBranch.", field="targetBranch")
        _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
        return e
    if authorUserId is not None:
        e = _validate_pattern(authorUserId, r"^yunx_idn_01J[0-9A-Z]+$", "authorUserId")
        if e:
            _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
            return e
    if reviewerUserId is not None:
        e = _validate_pattern(reviewerUserId, r"^yunx_idn_01J[0-9A-Z]+$", "reviewerUserId")
        if e:
            _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
            return e

    if sortBy is None:
        sortBy = "created_at"
    if not _is_str(sortBy) or sortBy not in ("created_at", "updated_at"):
        e = _err("VALIDATION_ERROR", "Invalid sortBy.", field="sortBy")
        _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
        return e

    if sortOrder is None:
        sortOrder = "desc"
    if not _is_str(sortOrder) or sortOrder not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "Invalid sortOrder.", field="sortOrder")
        _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
        return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "Invalid limit.", field="limit")
        _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
        return e

    cur_obj = _decode_cursor(cursor)
    if isinstance(cur_obj, dict) and "error" in cur_obj:
        _log("VALIDATION_ERROR", cur_obj["error"]["message"], token_row.get("id"))
        return cur_obj
    if cur_obj is not None:
        # expected shape
        if cur_obj.get("v") != 1 or cur_obj.get("org") != organizationId or cur_obj.get("repo") != repositoryId:
            e = _err("VALIDATION_ERROR", "Cursor does not match this query scope.", field="cursor")
            _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
            return e
        if cur_obj.get("sortBy") != sortBy or cur_obj.get("sortOrder") != sortOrder:
            e = _err("VALIDATION_ERROR", "Cursor does not match this sort order.", field="cursor")
            _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
            return e

    # ---- Authorization scope: token must belong to organization; plus org/repo must exist ----
    # Organization must exist as identity org row
    org_row = next((r for r in identity if isinstance(r, dict) and r.get("id") == organizationId and r.get("entity_type") == "organization" and r.get("status") != "deleted"), None)
    if org_row is None:
        _log("NOT_FOUND", "Organization not found.", token_row.get("id"))
        return _err("NOT_FOUND", "Organization not found.", field="organizationId")

    if token_row.get("organization_id") != organizationId:
        # allow if user is member of requested org
        membership = next((r for r in identity if isinstance(r, dict) and r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("user_id") == token_row.get("user_id") and r.get("organization_id") == organizationId), None)
        if membership is None:
            _log("UNAUTHORIZED", "Token not authorized for organization.", token_row.get("id"))
            return _err("UNAUTHORIZED", "Not authorized for this organization.")

    codeup = _load("codeup.json")
    repo_row = next((r for r in codeup if isinstance(r, dict) and r.get("id") == repositoryId and r.get("entity_type") == "repository" and r.get("organization_id") == organizationId and r.get("status") != "deleted"), None)
    if repo_row is None:
        _log("NOT_FOUND", "Repository not found.", token_row.get("id"))
        return _err("NOT_FOUND", "Repository not found.", field="repositoryId")

    # ---- Query ----
    rows = [
        r for r in codeup
        if isinstance(r, dict)
        and r.get("entity_type") == "change_request"
        and r.get("organization_id") == organizationId
        and r.get("repository_id") == repositoryId
        and r.get("status") != "deleted"
    ]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if sourceBranch is not None:
        rows = [r for r in rows if r.get("source_branch") == sourceBranch]
    if targetBranch is not None:
        rows = [r for r in rows if r.get("target_branch") == targetBranch]
    if authorUserId is not None:
        rows = [r for r in rows if r.get("author_user_id") == authorUserId]
    if reviewerUserId is not None:
        rows = [r for r in rows if isinstance(r.get("reviewer_user_ids"), list) and reviewerUserId in r.get("reviewer_user_ids")]

    def _dt_key(v):
        # ISO 8601 Z; lexicographic works if consistent, but guard None.
        if v is None:
            return ""
        if isinstance(v, str):
            return v
        return str(v)

    reverse = (sortOrder == "desc")
    rows.sort(key=lambda r: (_dt_key(r.get(sortBy)), r.get("id", "")), reverse=reverse)

    total = len(rows)

    start = 0
    if cur_obj is not None:
        start = cur_obj.get("offset")
        if not isinstance(start, int) or start < 0:
            e = _err("VALIDATION_ERROR", "Invalid cursor offset.", field="cursor")
            _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
            return e
        if start > total:
            start = total

    page = rows[start:start + limit]
    next_cursor = None
    if start + limit < total:
        next_cursor = _encode_cursor({"v": 1, "org": organizationId, "repo": repositoryId, "sortBy": sortBy, "sortOrder": sortOrder, "offset": start + limit})

    # update token last_used_at
    now = _now()
    for r in identity:
        if isinstance(r, dict) and r.get("id") == token_row.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now if (isinstance(r.get("created_at"), str) and now >= r.get("created_at")) else r.get("updated_at", now)
            break
    try:
        _save("identity.json", identity)
    except Exception:
        pass

    _log("OK", None, token_row.get("id"), extra={"count": len(page), "total": total})

    return {
        "data": page,
        "meta": {"total": total, "limit": limit, "cursor": next_cursor, "has_more": next_cursor is not None, "sort_by": sortBy, "sort_order": sortOrder},
    }

def create_change_request(organizationId, repositoryId, sourceBranch, targetBranch, title=None, description=None, reviewerUserIds=None, workItemIds=None, sourceProjectId=None, targetProjectId=None, commentBody=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "create_change_request"
    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _new_id(prefix):
        return prefix + hashlib.sha1(f"{prefix}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:18].upper()

    def _ensure_request_log():
        p = os.path.join(_DB, "request_log.json")
        if not os.path.exists(p):
            _save("request_log.json", [])
            return []
        d = _load("request_log.json")
        if not isinstance(d, list):
            _save("request_log.json", [])
            return []
        return d

    def _log(token_row, status, error_code=None, message=None, extra=None):
        logs = _ensure_request_log()
        row = {
            "id": "yunx_req_" + hashlib.sha1(f"{endpoint}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "token_id": token_row.get("id") if isinstance(token_row, dict) else None,
            "organization_id": token_row.get("organization_id") if isinstance(token_row, dict) else None,
            "user_id": token_row.get("user_id") if isinstance(token_row, dict) else None,
            "request": {"organizationId": organizationId, "repositoryId": repositoryId, "sourceBranch": sourceBranch, "targetBranch": targetBranch},
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    def _resolve_token_context():
        identities = _load("identity.json")
        if not isinstance(identities, list):
            identities = []
        for tok in identities:
            if tok.get("entity_type") != "api_token" or tok.get("status") != "active":
                continue
            uid = tok.get("user_id")
            oid = tok.get("organization_id")
            if not isinstance(uid, str) or not uid or not isinstance(oid, str) or not oid:
                continue
            u = next((r for r in identities if r.get("id") == uid and r.get("entity_type") == "user" and r.get("status") == "active"), None)
            o = next((r for r in identities if r.get("id") == oid and r.get("entity_type") == "organization" and r.get("status") == "active"), None)
            if not u or not o:
                continue
            m = next((r for r in identities if r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("user_id") == uid and r.get("organization_id") == oid), None)
            if not m:
                continue
            exp = tok.get("expires_at")
            if isinstance(exp, str) and exp:
                exp_dt = _parse_dt(exp)
                if exp_dt is not None and exp_dt <= datetime.datetime.utcnow():
                    continue
            return tok, identities
        return None, identities

    # Validate required fields (relax to schema only; no over-rejection)
    if not isinstance(organizationId, str) or re.match(r"^yunx_idn_01J[0-9A-Z]+$", organizationId) is None:
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid organizationId")
        return _err("VALIDATION_ERROR", "Invalid organizationId", organizationId=organizationId)
    if not isinstance(repositoryId, str) or re.match(r"^yunx_code_01J[0-9A-Z]+$", repositoryId) is None:
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid repositoryId")
        return _err("VALIDATION_ERROR", "Invalid repositoryId", repositoryId=repositoryId)
    if not isinstance(sourceBranch, str) or not sourceBranch:
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid sourceBranch")
        return _err("VALIDATION_ERROR", "Invalid sourceBranch", sourceBranch=sourceBranch)
    if not isinstance(targetBranch, str) or not targetBranch:
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid targetBranch")
        return _err("VALIDATION_ERROR", "Invalid targetBranch", targetBranch=targetBranch)

    if reviewerUserIds is not None and not isinstance(reviewerUserIds, list):
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "reviewerUserIds must be an array")
        return _err("VALIDATION_ERROR", "reviewerUserIds must be an array")
    if workItemIds is not None and not isinstance(workItemIds, list):
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "workItemIds must be an array")
        return _err("VALIDATION_ERROR", "workItemIds must be an array")

    token_row, identities = _resolve_token_context()
    if token_row is None:
        _log(None, "error", "UNAUTHORIZED", "Token is missing or invalid")
        return _err("UNAUTHORIZED", "Token is missing or invalid")

    # org context: token org takes precedence; request org must match repo org and token org
    token_org_id = token_row.get("organization_id")
    if organizationId != token_org_id:
        _log(token_row, "error", "UNAUTHORIZED", "Token not authorized for this organization")
        return _err("UNAUTHORIZED", "Token is not permitted to create change requests in this organization")

    codeup = _load("codeup.json")
    if not isinstance(codeup, list):
        codeup = []
    repo = next((r for r in codeup if r.get("entity_type") == "repository" and r.get("id") == repositoryId and r.get("status") != "deleted"), None)
    if repo is None:
        _log(token_row, "error", "NOT_FOUND", "Repository not found")
        return _err("NOT_FOUND", "Repository not found", repositoryId=repositoryId)
    if repo.get("organization_id") != organizationId:
        _log(token_row, "error", "CONFLICT", "Repository does not belong to organizationId")
        return _err("CONFLICT", "Repository does not belong to organizationId", repositoryId=repositoryId, organizationId=organizationId)

    # validate reviewers are users with active membership in org
    reviewer_ids = reviewerUserIds if isinstance(reviewerUserIds, list) else None
    if reviewer_ids is not None:
        for rid in reviewer_ids:
            if not isinstance(rid, str) or re.match(r"^yunx_idn_01J[0-9A-Z]+$", rid) is None:
                _log(token_row, "error", "VALIDATION_ERROR", "Invalid reviewerUserIds entry", reviewerUserId=rid)
                return _err("VALIDATION_ERROR", "Invalid reviewerUserIds entry", reviewerUserId=rid)
            u = next((r for r in identities if r.get("id") == rid and r.get("entity_type") == "user" and r.get("status") == "active"), None)
            if not u:
                _log(token_row, "error", "NOT_FOUND", "Reviewer user not found", reviewerUserId=rid)
                return _err("NOT_FOUND", "Reviewer user not found", reviewerUserId=rid)
            m = next((r for r in identities if r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("user_id") == rid and r.get("organization_id") == organizationId), None)
            if not m:
                _log(token_row, "error", "VALIDATION_ERROR", "Reviewer is not a member of the organization", reviewerUserId=rid)
                return _err("VALIDATION_ERROR", "reviewerUserIds must belong to the same organization via active membership", reviewerUserId=rid)

    # validate work items exist if provided
    if workItemIds is not None:
        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []
        for wid in workItemIds:
            if not isinstance(wid, str) or re.match(r"^yunx_wi_01J[0-9A-Z]+$", wid) is None:
                _log(token_row, "error", "VALIDATION_ERROR", "Invalid workItemIds entry", workItemId=wid)
                return _err("VALIDATION_ERROR", "Invalid workItemIds entry", workItemId=wid)
            wi = next((r for r in projects if r.get("id") == wid and r.get("entity_type") == "work_item" and r.get("status") != "deleted"), None)
            if wi is None or wi.get("organization_id") != organizationId:
                _log(token_row, "error", "NOT_FOUND", "Work item not found", workItemId=wid)
                return _err("NOT_FOUND", "Work item not found", workItemId=wid)

    # create CR
    now = _now()
    cr_id = _new_id("yunx_code_")
    cr = {
        "id": cr_id,
        "entity_type": "change_request",
        "status": "open",
        "organization_id": organizationId,
        "repository_id": repositoryId,
        "project_id": repo.get("project_id"),
        "source_branch": sourceBranch,
        "target_branch": targetBranch,
        "title": title if isinstance(title, str) else None,
        "description": description if isinstance(description, str) else None,
        "reviewer_user_ids": reviewer_ids,
        "work_item_ids": workItemIds if isinstance(workItemIds, list) else None,
        "created_at": now,
        "updated_at": now,
    }
    # optional cross-project context (best-effort store)
    if isinstance(sourceProjectId, str):
        cr["source_project_id"] = sourceProjectId
    if isinstance(targetProjectId, str):
        cr["target_project_id"] = targetProjectId

    codeup.append(cr)

    created_comment = None
    if isinstance(commentBody, str) and commentBody.strip():
        cmt_id = _new_id("yunx_code_")
        created_comment = {
            "id": cmt_id,
            "entity_type": "change_request_comment",
            "status": "active",
            "organization_id": organizationId,
            "repository_id": repositoryId,
            "change_request_id": cr_id,
            "author_user_id": token_row.get("user_id"),
            "comment_body": commentBody,
            "created_at": now,
            "updated_at": now,
        }
        codeup.append(created_comment)

    _save("codeup.json", codeup)

    # touch token last_used_at
    if isinstance(identities, list):
        for r in identities:
            if r.get("id") == token_row.get("id"):
                r["last_used_at"] = now
                r["updated_at"] = now
                break
        _save("identity.json", identities)

    _log(token_row, "ok")
    return {"change_request": cr, "initial_comment": created_comment}

