def list_change_request_comments(changeRequestId, sortOrder=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_change_request_comments"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            return obj
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    def _encode_cursor(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    identity = _load("identity.json")
    tokens = [r for r in identity if isinstance(r, dict) and r.get("entity_type") == "api_token" and r.get("status") == "active" and r.get("user_id") and r.get("organization_id")]
    token_row = tokens[0] if tokens else None

    reqlog_file = "request_log.json"
    reqlog = _load(reqlog_file)
    if not isinstance(reqlog, list):
        reqlog = []

    def _log(status_code, message=None, used_token_id=None, extra=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "yunx_req_" + hashlib.sha1(f"{endpoint}:{_now()}:{latency_ms}:{os.getpid()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status_code,
            "latency_ms": latency_ms,
            "token_id": used_token_id,
        }
        if message:
            row["message"] = message
        if isinstance(extra, dict):
            row.update(extra)
        reqlog.append(row)
        try:
            _save(reqlog_file, reqlog)
        except Exception:
            pass

    if token_row is None:
        _log("UNAUTHORIZED", "No active api_token available to authorize request.", None)
        return _err("UNAUTHORIZED", "No active API token available.")

    if not isinstance(changeRequestId, str) or not re.match(r"^yunx_code_01J[0-9A-Z]+$", changeRequestId):
        e = _err("VALIDATION_ERROR", "Invalid changeRequestId.", field="changeRequestId")
        _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
        return e

    if sortOrder is None:
        sortOrder = "asc"
    if not isinstance(sortOrder, str) or sortOrder not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "Invalid sortOrder.", field="sortOrder")
        _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
        return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "Invalid limit.", field="limit")
        _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
        return e

    cur_obj = _decode_cursor(cursor)
    if isinstance(cur_obj, dict) and "error" in cur_obj:
        _log("VALIDATION_ERROR", cur_obj["error"]["message"], token_row.get("id"))
        return cur_obj
    if cur_obj is not None:
        if cur_obj.get("v") != 1 or cur_obj.get("cr") != changeRequestId or cur_obj.get("sortOrder") != sortOrder:
            e = _err("VALIDATION_ERROR", "Cursor does not match this query.", field="cursor")
            _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
            return e

    codeup = _load("codeup.json")
    cr = next((r for r in codeup if isinstance(r, dict) and r.get("id") == changeRequestId and r.get("entity_type") == "change_request" and r.get("status") != "deleted"), None)
    if cr is None:
        _log("NOT_FOUND", "Change request not found.", token_row.get("id"))
        return _err("NOT_FOUND", "Change request not found.", field="changeRequestId")

    org_id = cr.get("organization_id")
    if token_row.get("organization_id") != org_id:
        membership = next((r for r in identity if isinstance(r, dict) and r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("user_id") == token_row.get("user_id") and r.get("organization_id") == org_id), None)
        if membership is None:
            _log("UNAUTHORIZED", "Token not authorized to read comments in this organization.", token_row.get("id"))
            return _err("UNAUTHORIZED", "Not authorized to read comments on this change request.")

    rows = [
        r for r in codeup
        if isinstance(r, dict)
        and r.get("entity_type") == "change_request_comment"
        and r.get("change_request_id") == changeRequestId
        and r.get("status") != "deleted"
    ]

    reverse = (sortOrder == "desc")
    # created_at order, tie-breaker id
    rows.sort(key=lambda r: ((r.get("created_at") or ""), r.get("id") or ""), reverse=reverse)

    total = len(rows)
    start = 0
    if cur_obj is not None:
        start = cur_obj.get("offset")
        if not isinstance(start, int) or start < 0:
            e = _err("VALIDATION_ERROR", "Invalid cursor offset.", field="cursor")
            _log("VALIDATION_ERROR", e["error"]["message"], token_row.get("id"))
            return e
        if start > total:
            start = total

    page = rows[start:start + limit]
    next_cursor = None
    if start + limit < total:
        next_cursor = _encode_cursor({"v": 1, "cr": changeRequestId, "sortOrder": sortOrder, "offset": start + limit})

    # update token last_used_at
    now = _now()
    for r in identity:
        if isinstance(r, dict) and r.get("id") == token_row.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now if (isinstance(r.get("created_at"), str) and now >= r.get("created_at")) else r.get("updated_at", now)
            break
    try:
        _save("identity.json", identity)
    except Exception:
        pass

    _log("OK", None, token_row.get("id"), extra={"count": len(page), "total": total, "change_request_id": changeRequestId})

    return {
        "data": page,
        "meta": {"total": total, "limit": limit, "cursor": next_cursor, "has_more": next_cursor is not None, "sort_order": sortOrder},
    }

def list_change_request_patch_sets(change_request_id, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _record(endpoint, token_id, status_code, error_code=None):
        logs = _load("request_log.json")
        entry = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": token_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        logs.append(entry)
        _save("request_log.json", logs)

    def _dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(float(s))
        if isinstance(s, str):
            x = s.strip()
            if x.endswith("Z"):
                x = x[:-1]
            try:
                return datetime.datetime.fromisoformat(x)
            except ValueError:
                return None
        return None

    def _find_active_token_context():
        identities = _load("identity.json")
        # Find any active api_token with valid org and user refs.
        for tok in identities:
            if tok.get("entity_type") != "api_token" or tok.get("status") != "active":
                continue
            org_id = tok.get("organization_id")
            user_id = tok.get("user_id")
            if not isinstance(org_id, str) or not isinstance(user_id, str):
                continue
            org = next((r for r in identities if r.get("id") == org_id and r.get("entity_type") == "organization" and r.get("status") != "deleted"), None)
            usr = next((r for r in identities if r.get("id") == user_id and r.get("entity_type") == "user" and r.get("status") != "deleted"), None)
            if not org or not usr:
                continue
            mem = next((r for r in identities if r.get("entity_type") == "membership" and r.get("organization_id") == org_id and r.get("user_id") == user_id and r.get("status") == "active"), None)
            if not mem:
                continue
            return tok, org, usr, mem
        return None, None, None, None

    token, org, usr, mem = _find_active_token_context()
    if not token:
        _record("list_change_request_patch_sets", None, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid access token.")

    # Rate limit: 120 req/min per token (simple sliding window).
    logs = _load("request_log.json")
    window_start = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    used = 0
    for e in logs:
        if e.get("credential_id") != token.get("id"):
            continue
        ts = _dt(e.get("timestamp"))
        if ts and ts >= window_start:
            used += 1
    if used >= 120:
        _record("list_change_request_patch_sets", token.get("id"), 429, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Validation
    if not isinstance(change_request_id, str) or not re.match(r"^yunx_code_01J[A-Za-z0-9]+$", change_request_id):
        _record("list_change_request_patch_sets", token.get("id"), 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid change_request_id.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _record("list_change_request_patch_sets", token.get("id"), 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")

    if cursor is not None and not isinstance(cursor, str):
        _record("list_change_request_patch_sets", token.get("id"), 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.")

    if sort_by is None:
        sort_by = "patch_set_number"
    if sort_order is None:
        sort_order = "asc"
    if sort_by not in ("patch_set_number", "created_at", "updated_at"):
        _record("list_change_request_patch_sets", token.get("id"), 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort_by.")
    if sort_order not in ("asc", "desc"):
        _record("list_change_request_patch_sets", token.get("id"), 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort_order.")

    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if obj.get("v") != 1 or obj.get("op") != "offset":
                raise ValueError("bad cursor")
            offset = int(obj.get("offset", 0))
            if offset < 0:
                raise ValueError("bad offset")
        except Exception:
            _record("list_change_request_patch_sets", token.get("id"), 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    codeup = _load("codeup.json")

    cr = next((r for r in codeup
               if r.get("id") == change_request_id
               and r.get("entity_type") == "change_request"
               and r.get("organization_id") == org.get("id")
               and r.get("status") != "deleted"), None)
    if not cr:
        _record("list_change_request_patch_sets", token.get("id"), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Change request not found.")

    patch_sets = [r for r in codeup
                  if r.get("entity_type") == "patch_set"
                  and r.get("change_request_id") == change_request_id
                  and r.get("organization_id") == org.get("id")
                  and r.get("status") != "deleted"]

    def _sort_key(r):
        if sort_by == "patch_set_number":
            v = r.get("patch_set_number")
            return (v if isinstance(v, int) else 10**18, _dt(r.get("created_at")) or datetime.datetime.min, r.get("id") or "")
        if sort_by == "created_at":
            return (_dt(r.get("created_at")) or datetime.datetime.min, r.get("id") or "")
        return (_dt(r.get("updated_at")) or datetime.datetime.min, r.get("id") or "")

    reverse = (sort_order == "desc")
    patch_sets.sort(key=_sort_key, reverse=reverse)

    total = len(patch_sets)
    page = patch_sets[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"v": 1, "op": "offset", "offset": next_offset}).encode("utf-8")).decode("utf-8")

    resp = {
        "data": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "sort": {"by": sort_by, "order": sort_order},
        "context": {"organization_id": org.get("id"), "user_id": usr.get("id")},
    }
    _record("list_change_request_patch_sets", token.get("id"), 200, None)
    return resp

