    if organization_id is not None:
        if not isinstance(organization_id, str) or not re.match(r"^yunx_idn_01J[A-Za-z0-9]+$", organization_id):
            _record("get_current_organization_info", token.get("id"), 400, "VALIDATION_ERROR")
