                raise ValueError("bad offset")
        except Exception:
            _record("get_user_organizations", token.get("id"), 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # Find orgs where an active membership exists for this user
    memberships = [r for r in identities
                   if r.get("entity_type") == "membership"
                   and r.get("user_id") == usr.get("id")
                   and r.get("status") == "active"
                   and isinstance(r.get("organization_id"), str)]

    org_ids = []
    seen = set()
    for m in memberships:
        oid = m.get("organization_id")
        if oid and oid not in seen:
            seen.add(oid)
            org_ids.append(oid)

    orgs = [r for r in identities
            if r.get("entity_type") == "organization"
            and r.get("id") in seen]

    if status is not None:
        orgs = [o for o in orgs if o.get("status") == status]

    # stable ordering: token org first, then by display_name, then id
    def _name(o):
        v = o.get("display_name")
        return v.lower() if isinstance(v, str) else ""
    orgs.sort(key=lambda o: (_name(o), o.get("id") or ""))
    if token_org and token_org.get("id") in seen:
        orgs = [token_org] + [o for o in orgs if o.get("id") != token_org.get("id")]

    total = len(orgs)
    page = orgs[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"v": 1, "op": "offset", "offset": next_offset}).encode("utf-8")).decode("utf-8")

    resp = {
        "data": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "context": {"user_id": usr.get("id"), "token_org_id": token_org.get("id") if token_org else None},
    }
    _record("get_user_organizations", token.get("id"), 200, None)
    return resp

def get_current_user(user_id=None, **_extra):
