        entry = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": token_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        logs.append(entry)
        _save("request_log.json", logs)

    def _dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(float(s))
        if isinstance(s, str):
            x = s.strip()
            if x.endswith("Z"):
                x = x[:-1]
            try:
                return datetime.datetime.fromisoformat(x)
            except ValueError:
                return None
        return None

    def _find_active_token_context():
        identities = _load("identity.json")
        for tok in identities:
            if tok.get("entity_type") != "api_token" or tok.get("status") != "active":
                continue
            org_id = tok.get("organization_id")
            uid = tok.get("user_id")
            if not isinstance(org_id, str) or not isinstance(uid, str):
                continue
            usr = next((r for r in identities if r.get("id") == uid and r.get("entity_type") == "user" and r.get("status") != "deleted"), None)
            org = next((r for r in identities if r.get("id") == org_id and r.get("entity_type") == "organization" and r.get("status") != "deleted"), None)
            if not usr or not org:
                continue
            mem = next((r for r in identities if r.get("entity_type") == "membership" and r.get("organization_id") == org_id and r.get("user_id") == uid and r.get("status") == "active"), None)
            if not mem:
                continue
            return tok, usr, org, identities
        return None, None, None, _load("identity.json")

    token, token_user, token_org, identities = _find_active_token_context()
    if not token:
        _record("get_current_user", None, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid access token.")

    # Rate limit: 120 req/min per token.
    logs = _load("request_log.json")
    window_start = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    used = 0
    for e in logs:
        if e.get("credential_id") != token.get("id"):
            continue
        ts = _dt(e.get("timestamp"))
        if ts and ts >= window_start:
            used += 1
    if used >= 120:
        _record("get_current_user", token.get("id"), 429, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # If user_id provided, must be well-formed and accessible (same org via active membership)
    if user_id is not None:
        if not isinstance(user_id, str) or not re.match(r"^yunx_idn_01J[A-Za-z0-9]+$", user_id):
            _record("get_current_user", token.get("id"), 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid user_id.")
        usr = next((r for r in identities
                    if r.get("id") == user_id and r.get("entity_type") == "user" and r.get("status") != "deleted"), None)
        if not usr:
            _record("get_current_user", token.get("id"), 404, "NOT_FOUND")
            return _err("NOT_FOUND", "User not found.")

        # Accessibility: user is visible if they share an organization with caller (active membership).
        caller_org_ids = {r.get("organization_id") for r in identities
                          if r.get("entity_type") == "membership"
                          and r.get("user_id") == token_user.get("id")
                          and r.get("status") == "active"
                          and isinstance(r.get("organization_id"), str)}
        target_org_ids = {r.get("organization_id") for r in identities
                          if r.get("entity_type") == "membership"
                          and r.get("user_id") == user_id
                          and r.get("status") == "active"
                          and isinstance(r.get("organization_id"), str)}
