            return " ".join([
                str(r.get("name") or ""),
                str(r.get("key") or ""),
                str(r.get("description") or ""),
            ]).lower()
        rows = [r for r in rows if q in _txt(r)]

    def _sort_key(r):
        if sort_by in ("created_at", "updated_at"):
            dt = _parse_dt(r.get(sort_by))
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        v = r.get(sort_by)
        return (v or "").lower() if isinstance(v, str) else ""

