            return _err("VALIDATION_ERROR", "assignee_user_id is malformed.", field="assignee_user_id")
    if reporter_user_id is not None:
        if not isinstance(reporter_user_id, str) or not re.match(r"^yunx_idn_01J[A-Za-z0-9]+$", reporter_user_id):
            _log("search_workitems", token.get("id"), 400, _t0, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "reporter_user_id is malformed.", field="reporter_user_id")

    if priority_min is not None and not isinstance(priority_min, int):
