            return _err("VALIDATION_ERROR", "labels must be an array of strings.", field="labels")

    if sprint is not None and not isinstance(sprint, str):
        _log("search_workitems", token.get("id"), 400, _t0, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sprint must be a string.", field="sprint")

