    rows = [r for r in projects if isinstance(r, dict) and r.get("entity_type") == "work_item" and r.get("organization_id") == org_id]

    if project_id is not None:
        rows = [r for r in rows if r.get("project_id") == project_id]
    if work_item_type is not None:
        rows = [r for r in rows if r.get("work_item_type") == work_item_type]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    if assignee_user_id is not None:
        rows = [r for r in rows if r.get("assignee_user_id") == assignee_user_id]
    if reporter_user_id is not None:
        rows = [r for r in rows if r.get("reporter_user_id") == reporter_user_id]

    if priority_min is not None:
        rows = [r for r in rows if isinstance(r.get("priority"), int) and r.get("priority") >= priority_min]
    if priority_max is not None:
        rows = [r for r in rows if isinstance(r.get("priority"), int) and r.get("priority") <= priority_max]

    if labels is not None and len(labels) > 0:
        want = set([x for x in labels if isinstance(x, str)])
        def _has_all(r):
            have = r.get("labels")
            if not isinstance(have, list):
                return False
            return want.issubset(set([x for x in have if isinstance(x, str)]))
        rows = [r for r in rows if _has_all(r)]

    if sprint is not None:
        rows = [r for r in rows if r.get("sprint") == sprint]

    def _dt_in_range(v, a_from, a_to):
        if v is None:
            return False
        dtv = _parse_dt(v) if isinstance(v, str) else (v if isinstance(v, datetime.datetime) else None)
        if dtv is None:
            return False
        # normalize naive to UTC
        if dtv.tzinfo is None:
            dtv = dtv.replace(tzinfo=datetime.timezone.utc)
        if a_from is not None:
            af = a_from if a_from.tzinfo else a_from.replace(tzinfo=datetime.timezone.utc)
            if dtv < af:
                return False
        if a_to is not None:
            at = a_to if a_to.tzinfo else a_to.replace(tzinfo=datetime.timezone.utc)
            if dtv > at:
                return False
        return True

    if parsed["due_date_from"] is not None or parsed["due_date_to"] is not None:
        rows = [r for r in rows if _dt_in_range(r.get("due_date"), parsed["due_date_from"], parsed["due_date_to"])]
    if parsed["created_at_from"] is not None or parsed["created_at_to"] is not None:
        rows = [r for r in rows if _dt_in_range(r.get("created_at"), parsed["created_at_from"], parsed["created_at_to"])]
    if parsed["updated_at_from"] is not None or parsed["updated_at_to"] is not None:
        rows = [r for r in rows if _dt_in_range(r.get("updated_at"), parsed["updated_at_from"], parsed["updated_at_to"])]

    if query:
        q = query.strip().lower()
        def _txt(r):
            return " ".join([str(r.get("name") or ""), str(r.get("description") or "")]).lower()
        rows = [r for r in rows if q in _txt(r)]

    def _sort_key(r):
        if sort_by in ("created_at", "updated_at", "due_date"):
            dt = _parse_dt(r.get(sort_by))
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        # priority
        p = r.get("priority")
        return p if isinstance(p, int) else 10**9

    reverse = (sort_order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # update token last_used_at
    now = _now()
    for r in identity:
        if isinstance(r, dict) and r.get("id") == token.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now if (r.get("updated_at") is None or str(r.get("updated_at")) <= now) else r.get("updated_at")
            break
    _save("identity.json", identity)

    _log("search_workitems", token.get("id"), 200, _t0, None)
    return {"work_items": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}

def get_pipeline(organization_id, pipeline_id, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_pipeline"
    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _ensure_request_log():
        p = os.path.join(_DB, "request_log.json")
        if not os.path.exists(p):
            _save("request_log.json", [])
            return []
        d = _load("request_log.json")
        if not isinstance(d, list):
            _save("request_log.json", [])
            return []
        return d

    def _log(token_row, status, error_code=None, message=None, extra=None):
        logs = _ensure_request_log()
        row = {
            "id": "yunx_req_" + hashlib.sha1(f"{endpoint}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "token_id": token_row.get("id") if isinstance(token_row, dict) else None,
            "organization_id": token_row.get("organization_id") if isinstance(token_row, dict) else None,
            "user_id": token_row.get("user_id") if isinstance(token_row, dict) else None,
            "request": {"organization_id": organization_id, "pipeline_id": pipeline_id},
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    def _resolve_token_context():
        identities = _load("identity.json")
        if not isinstance(identities, list):
            identities = []
        for tok in identities:
            if tok.get("entity_type") != "api_token" or tok.get("status") != "active":
                continue
            uid = tok.get("user_id")
            oid = tok.get("organization_id")
            if not isinstance(uid, str) or not uid or not isinstance(oid, str) or not oid:
                continue
            u = next((r for r in identities if r.get("id") == uid and r.get("entity_type") == "user" and r.get("status") == "active"), None)
            o = next((r for r in identities if r.get("id") == oid and r.get("entity_type") == "organization" and r.get("status") == "active"), None)
            if not u or not o:
                continue
            m = next((r for r in identities if r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("user_id") == uid and r.get("organization_id") == oid), None)
            if not m:
                continue
            exp = tok.get("expires_at")
            if isinstance(exp, str) and exp:
                exp_dt = _parse_dt(exp)
                if exp_dt is not None and exp_dt <= datetime.datetime.utcnow():
                    continue
            return tok, identities
        return None, identities

    if not isinstance(organization_id, str) or re.match(r"^yunx_idn_01J[a-zA-Z0-9]+$", organization_id) is None:
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid organization_id")
        return _err("VALIDATION_ERROR", "Invalid organization_id", organization_id=organization_id)
    if not isinstance(pipeline_id, str) or re.match(r"^yunx_pip_01J[a-zA-Z0-9]+$", pipeline_id) is None:
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid pipeline_id")
        return _err("VALIDATION_ERROR", "Invalid pipeline_id", pipeline_id=pipeline_id)

    token_row, identities = _resolve_token_context()
    if token_row is None:
        _log(None, "error", "UNAUTHORIZED", "Token is missing or invalid")
        return _err("UNAUTHORIZED", "Token is missing or invalid")

    if token_row.get("organization_id") != organization_id:
        _log(token_row, "error", "UNAUTHORIZED", "Token not authorized for this organization")
        return _err("UNAUTHORIZED", "Token is not permitted to access this organization's pipelines")

    pipelines = _load("pipelines.json")
    if not isinstance(pipelines, list):
        pipelines = []
    pipe = next((r for r in pipelines if r.get("entity_type") == "pipeline" and r.get("id") == pipeline_id and r.get("organization_id") == organization_id and r.get("status") != "deleted"), None)
    if pipe is None:
        _log(token_row, "error", "NOT_FOUND", "Pipeline not found")
        return _err("NOT_FOUND", "Pipeline not found", pipeline_id=pipeline_id, organization_id=organization_id)

    # touch token last_used_at
    now = _now()
    for r in identities:
        if r.get("id") == token_row.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now
            break
    _save("identity.json", identities)

    _log(token_row, "ok")
    return {"pipeline": pipe}

def list_pipelines(organization_id, status=None, name=None, name_contains=None, created_after=None, created_before=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_pipelines"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return datetime.datetime.fromisoformat(s.replace(" ", "T"))
        except Exception:
            return None

    def _audit(status_str, credential_id=None, organization_id_used=None, details=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"yunx_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "organization_id": organization_id_used,
            "status": status_str,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "details": details or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(token_row):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        token_id = token_row.get("id")
        window_s = 60
        limit_per_min = 120
        used = 0
        for r in reversed(logs[-2000:]):
            if r.get("credential_id") != token_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_s:
                used += 1
        if used >= limit_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=limit_per_min)
        return None

    def _resolve_token():
        ident = _load("identity.json")
        if not isinstance(ident, list):
            ident = []
        active_tokens = [r for r in ident if r.get("entity_type") == "api_token" and r.get("status") == "active"]
        for tok in active_tokens:
            if not tok.get("user_id") or not tok.get("organization_id"):
                continue
            user = next((u for u in ident if u.get("id") == tok.get("user_id") and u.get("entity_type") == "user" and u.get("status") == "active"), None)
            org = next((o for o in ident if o.get("id") == tok.get("organization_id") and o.get("entity_type") == "organization" and o.get("status") == "active"), None)
            mem = next((m for m in ident if m.get("entity_type") == "membership" and m.get("status") == "active" and m.get("organization_id") == tok.get("organization_id") and m.get("user_id") == tok.get("user_id")), None)
            if user and org and mem:
                return tok, user, org
        return None, None, None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    # Validate inputs
    if not isinstance(organization_id, str) or not re.match(r"^yunx_idn_01J[a-zA-Z0-9]+$", organization_id):
        tok, _, _ = _resolve_token()
        _audit("error", credential_id=(tok or {}).get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "organization_id is missing or malformed")
    if status is not None and (not isinstance(status, str) or status not in ("active", "disabled", "deleted")):
        tok, _, _ = _resolve_token()
        _audit("error", credential_id=(tok or {}).get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid status filter")
    if name is not None and not isinstance(name, str):
        tok, _, _ = _resolve_token()
        _audit("error", credential_id=(tok or {}).get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "name must be a string")
    if name_contains is not None and not isinstance(name_contains, str):
        tok, _, _ = _resolve_token()
        _audit("error", credential_id=(tok or {}).get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "name_contains must be a string")
    if sort_by is not None and (not isinstance(sort_by, str) or sort_by not in ("created_at", "updated_at", "name")):
        tok, _, _ = _resolve_token()
        _audit("error", credential_id=(tok or {}).get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid sort_by")
    if sort_order is not None and (not isinstance(sort_order, str) or sort_order not in ("asc", "desc")):
        tok, _, _ = _resolve_token()
        _audit("error", credential_id=(tok or {}).get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid sort_order")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        tok, _, _ = _resolve_token()
        _audit("error", credential_id=(tok or {}).get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    ca = _parse_dt(created_after) if created_after is not None else None
    cb = _parse_dt(created_before) if created_before is not None else None
    if created_after is not None and ca is None:
        tok, _, _ = _resolve_token()
        _audit("error", credential_id=(tok or {}).get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "created_after must be an ISO date-time string")
    if created_before is not None and cb is None:
        tok, _, _ = _resolve_token()
        _audit("error", credential_id=(tok or {}).get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "created_before must be an ISO date-time string")
    if ca and cb and ca > cb:
        tok, _, _ = _resolve_token()
        _audit("error", credential_id=(tok or {}).get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "created_after must be <= created_before")

    cur_obj = _decode_cursor(cursor)
    if cursor is not None and cur_obj is None:
        tok, _, _ = _resolve_token()
        _audit("error", credential_id=(tok or {}).get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid cursor")

    tok, user, org = _resolve_token()
    if not tok:
        _audit("error", credential_id=None, organization_id_used=organization_id, details={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active API token context available")

    rl = _enforce_limits(tok)
    if rl:
        _audit("error", credential_id=tok.get("id"), organization_id_used=organization_id, details={"code": rl["error"]["code"]})
        return rl

    identities = _load("identity.json")
    if not isinstance(identities, list):
        identities = []
    org_row = next((o for o in identities if o.get("id") == organization_id and o.get("entity_type") == "organization" and o.get("status") != "deleted"), None)
    if not org_row:
        _audit("error", credential_id=tok.get("id"), organization_id_used=organization_id, details={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Organization not found")

    membership = next((m for m in identities if m.get("entity_type") == "membership" and m.get("status") == "active" and m.get("organization_id") == organization_id and m.get("user_id") == tok.get("user_id")), None)
    if not membership:
        _audit("error", credential_id=tok.get("id"), organization_id_used=organization_id, details={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Token does not grant access to list pipelines for this organization")

    pipes = _load("pipelines.json")
    if not isinstance(pipes, list):
        pipes = []

    rows = [p for p in pipes if p.get("entity_type") == "pipeline" and p.get("organization_id") == organization_id]
    if status is not None:
        rows = [p for p in rows if p.get("status") == status]
    if name is not None:
        rows = [p for p in rows if (p.get("name") or "") == name]
    if name_contains is not None:
        sub = name_contains.lower()
        rows = [p for p in rows if sub in (p.get("name") or "").lower()]
    if ca is not None:
        rows = [p for p in rows if (_parse_dt(p.get("created_at")) or datetime.datetime.min) > ca]
    if cb is not None:
        rows = [p for p in rows if (_parse_dt(p.get("created_at")) or datetime.datetime.max) < cb]

    sb = sort_by or "created_at"
    so = sort_order or "desc"
    reverse = (so == "desc")

    def _sort_key(p):
        if sb in ("created_at", "updated_at"):
            dt = _parse_dt(p.get(sb))
            return dt or datetime.datetime.min
        if sb == "name":
            return (p.get("name") or "").lower()
        return p.get("id") or ""

    rows.sort(key=_sort_key, reverse=reverse)

    offset = 0
    if cur_obj is not None:
        if cur_obj.get("org") != organization_id:
            _audit("error", credential_id=tok.get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Cursor does not match organization_id")
        if cur_obj.get("sb") != sb or cur_obj.get("so") != so:
            _audit("error", credential_id=tok.get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Cursor does not match sort parameters")
        off = cur_obj.get("off")
        if not isinstance(off, int) or off < 0:
            _audit("error", credential_id=tok.get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor offset")
        offset = off

    total = len(rows)
    page = rows[offset:offset + limit]
    next_cursor = None
    if offset + limit < total:
        next_cursor = _encode_cursor({"org": organization_id, "sb": sb, "so": so, "off": offset + limit})

    resp = {
        "pipelines": page,
        "pagination": {"total": total, "limit": limit, "has_more": next_cursor is not None, "next_cursor": next_cursor}
    }
    _audit("ok", credential_id=tok.get("id"), organization_id_used=organization_id, details={"code": "OK", "returned": len(page), "total": total})
    return resp

def smart_list_pipelines(organization_id, query, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "smart_list_pipelines"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return datetime.datetime.fromisoformat(s.replace(" ", "T"))
        except Exception:
            return None

    def _audit(status_str, credential_id=None, organization_id_used=None, details=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"yunx_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "organization_id": organization_id_used,
            "status": status_str,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "details": details or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(token_row):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        token_id = token_row.get("id")
        window_s = 60
        limit_per_min = 120
        used = 0
        for r in reversed(logs[-2000:]):
            if r.get("credential_id") != token_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_s:
                used += 1
        if used >= limit_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=limit_per_min)
        return None

    def _resolve_token():
        ident = _load("identity.json")
        if not isinstance(ident, list):
            ident = []
        active_tokens = [r for r in ident if r.get("entity_type") == "api_token" and r.get("status") == "active"]
        for tok in active_tokens:
            if not tok.get("user_id") or not tok.get("organization_id"):
                continue
            user = next((u for u in ident if u.get("id") == tok.get("user_id") and u.get("entity_type") == "user" and u.get("status") == "active"), None)
            org = next((o for o in ident if o.get("id") == tok.get("organization_id") and o.get("entity_type") == "organization" and o.get("status") == "active"), None)
            mem = next((m for m in ident if m.get("entity_type") == "membership" and m.get("status") == "active" and m.get("organization_id") == tok.get("organization_id") and m.get("user_id") == tok.get("user_id")), None)
            if user and org and mem:
                return tok, user, org
        return None, None, None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _start_of_day(d):
        return datetime.datetime(d.year, d.month, d.day)

    def _start_of_week(d):
        # Monday start
        sod = _start_of_day(d)
        return sod - datetime.timedelta(days=sod.weekday())

    def _parse_nl_time_window(q):
        ql = q.lower()
        now = datetime.datetime.utcnow()
        start = end = None

        if "today" in ql:
            start = _start_of_day(now)
            end = start + datetime.timedelta(days=1)
        elif "yesterday" in ql:
            end = _start_of_day(now)
            start = end - datetime.timedelta(days=1)
        elif "this week" in ql or "current week" in ql:
            start = _start_of_week(now)
            end = start + datetime.timedelta(days=7)
        elif "last week" in ql or "previous week" in ql:
            end = _start_of_week(now)
            start = end - datetime.timedelta(days=7)
        elif "this month" in ql or "current month" in ql:
            start = datetime.datetime(now.year, now.month, 1)
            if now.month == 12:
                end = datetime.datetime(now.year + 1, 1, 1)
            else:
                end = datetime.datetime(now.year, now.month + 1, 1)
        elif "last month" in ql or "previous month" in ql:
            if now.month == 1:
                start = datetime.datetime(now.year - 1, 12, 1)
                end = datetime.datetime(now.year, 1, 1)
            else:
                start = datetime.datetime(now.year, now.month - 1, 1)
                end = datetime.datetime(now.year, now.month, 1)
        else:
            # explicit ISO time window tokens: after:<iso> before:<iso>
            m_after = re.search(r"\bafter:(\S+)", q, flags=re.IGNORECASE)
            m_before = re.search(r"\bbefore:(\S+)", q, flags=re.IGNORECASE)
            if m_after:
                start = _parse_dt(m_after.group(1))
                if start is None:
                    return None, None, _err("VALIDATION_ERROR", "Cannot parse after: timestamp in query")
            if m_before:
                end = _parse_dt(m_before.group(1))
                if end is None:
                    return None, None, _err("VALIDATION_ERROR", "Cannot parse before: timestamp in query")

        if start and end and start > end:
            return None, None, _err("VALIDATION_ERROR", "Parsed time window is invalid (start > end)")
        return start, end, None

    # Validate inputs
    if not isinstance(organization_id, str) or not re.match(r"^yunx_idn_01J[a-zA-Z0-9]+$", organization_id):
        tok, _, _ = _resolve_token()
        _audit("error", credential_id=(tok or {}).get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "organization_id is missing or malformed")
    if not isinstance(query, str) or not query.strip():
        tok, _, _ = _resolve_token()
        _audit("error", credential_id=(tok or {}).get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    if status is not None and (not isinstance(status, str) or status not in ("active", "disabled", "deleted")):
        tok, _, _ = _resolve_token()
        _audit("error", credential_id=(tok or {}).get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid status filter")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        tok, _, _ = _resolve_token()
        _audit("error", credential_id=(tok or {}).get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    cur_obj = _decode_cursor(cursor)
    if cursor is not None and cur_obj is None:
        tok, _, _ = _resolve_token()
        _audit("error", credential_id=(tok or {}).get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid cursor")

    tok, user, org = _resolve_token()
    if not tok:
        _audit("error", credential_id=None, organization_id_used=organization_id, details={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active API token context available")

    rl = _enforce_limits(tok)
    if rl:
        _audit("error", credential_id=tok.get("id"), organization_id_used=organization_id, details={"code": rl["error"]["code"]})
        return rl

    identities = _load("identity.json")
    if not isinstance(identities, list):
        identities = []
    org_row = next((o for o in identities if o.get("id") == organization_id and o.get("entity_type") == "organization" and o.get("status") != "deleted"), None)
    if not org_row:
        _audit("error", credential_id=tok.get("id"), organization_id_used=organization_id, details={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Organization not found")
    membership = next((m for m in identities if m.get("entity_type") == "membership" and m.get("status") == "active" and m.get("organization_id") == organization_id and m.get("user_id") == tok.get("user_id")), None)
    if not membership:
        _audit("error", credential_id=tok.get("id"), organization_id_used=organization_id, details={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Token does not grant access to list pipelines for this organization")

    start, end, perr = _parse_nl_time_window(query)
    if perr:
        _audit("error", credential_id=tok.get("id"), organization_id_used=organization_id, details={"code": perr["error"]["code"]})
        return perr

    ql = query.lower()
    # Remove time phrases for text matching
    scrubbed = ql
    for phrase in ("today", "yesterday", "this week", "last week", "this month", "last month"):
        scrubbed = scrubbed.replace(phrase, " ")
    scrubbed = re.sub(r"\b(after|before):\S+", " ", scrubbed, flags=re.IGNORECASE)
    scrubbed = re.sub(r"\s+", " ", scrubbed).strip()

    pipes = _load("pipelines.json")
    if not isinstance(pipes, list):
        pipes = []
    runs = [r for r in pipes if r.get("entity_type") == "pipeline_run" and r.get("organization_id") == organization_id]

    def _run_time(r):
        return _parse_dt(r.get("started_at")) or _parse_dt(r.get("created_at")) or datetime.datetime.min

    allowed_pipeline_ids = None
    if start or end:
        ids = set()
        for r in runs:
            rt = _run_time(r)
            if start and rt < start:
                continue
            if end and rt >= end:
                continue
            pid = r.get("pipeline_id")
            if pid:
                ids.add(pid)
        allowed_pipeline_ids = ids

    pipelines_only = [p for p in pipes if p.get("entity_type") == "pipeline" and p.get("organization_id") == organization_id]
    if status is not None:
        pipelines_only = [p for p in pipelines_only if p.get("status") == status]
    if allowed_pipeline_ids is not None:
        pipelines_only = [p for p in pipelines_only if p.get("id") in allowed_pipeline_ids]

    if scrubbed:
        def _matches_text(p):
            hay = " ".join([(p.get("name") or ""), json.dumps(p.get("definition") or {}, ensure_ascii=False)])
            return scrubbed in hay.lower()
        pipelines_only = [p for p in pipelines_only if _matches_text(p)]

    # Sort by most recent activity in window if provided, else updated_at/created_at desc
    activity = {}
    if start or end:
        for r in runs:
            pid = r.get("pipeline_id")
            if not pid:
                continue
            rt = _run_time(r)
            if start and rt < start:
                continue
            if end and rt >= end:
                continue
            prev = activity.get(pid)
            if prev is None or rt > prev:
                activity[pid] = rt

    def _sort_key(p):
        pid = p.get("id")
        if pid in activity:
            return activity[pid]
        return _parse_dt(p.get("updated_at")) or _parse_dt(p.get("created_at")) or datetime.datetime.min

    pipelines_only.sort(key=_sort_key, reverse=True)

    offset = 0
    if cur_obj is not None:
        if cur_obj.get("org") != organization_id:
            _audit("error", credential_id=tok.get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Cursor does not match organization_id")
        if cur_obj.get("off") is None or not isinstance(cur_obj.get("off"), int) or cur_obj.get("off") < 0:
            _audit("error", credential_id=tok.get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor offset")
        # query must match exactly for cursor reuse
        if cur_obj.get("q") != query or cur_obj.get("st") != status:
            _audit("error", credential_id=tok.get("id"), organization_id_used=organization_id, details={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Cursor does not match query filters")
        offset = cur_obj.get("off")

    total = len(pipelines_only)
    page = pipelines_only[offset:offset + limit]
    next_cursor = None
    if offset + limit < total:
        next_cursor = _encode_cursor({"org": organization_id, "q": query, "st": status, "off": offset + limit})

    resp = {
        "pipelines": page,
        "applied_filters": {
            "organization_id": organization_id,
            "status": status,
            "time_window": {
                "start": (start.replace(microsecond=0).isoformat() + "Z") if start else None,
                "end": (end.replace(microsecond=0).isoformat() + "Z") if end else None
            },
            "text": scrubbed or None
        },
        "pagination": {"total": total, "limit": limit, "has_more": next_cursor is not None, "next_cursor": next_cursor}
    }
    _audit("ok", credential_id=tok.get("id"), organization_id_used=organization_id, details={"code": "OK", "returned": len(page), "total": total})
    return resp

def create_pipeline_run(organization_id, pipeline_id, parameters=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "create_pipeline_run"
    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _new_id(prefix):
        return prefix + hashlib.sha1(f"{prefix}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:18].upper()

    def _ensure_request_log():
        p = os.path.join(_DB, "request_log.json")
        if not os.path.exists(p):
            _save("request_log.json", [])
            return []
        d = _load("request_log.json")
        if not isinstance(d, list):
            _save("request_log.json", [])
            return []
        return d

    def _log(token_row, status, error_code=None, message=None, extra=None):
        logs = _ensure_request_log()
        row = {
            "id": "yunx_req_" + hashlib.sha1(f"{endpoint}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "token_id": token_row.get("id") if isinstance(token_row, dict) else None,
            "organization_id": token_row.get("organization_id") if isinstance(token_row, dict) else None,
            "user_id": token_row.get("user_id") if isinstance(token_row, dict) else None,
            "request": {"organization_id": organization_id, "pipeline_id": pipeline_id},
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    def _resolve_token_context():
        identities = _load("identity.json")
        if not isinstance(identities, list):
            identities = []
        for tok in identities:
            if tok.get("entity_type") != "api_token" or tok.get("status") != "active":
                continue
            uid = tok.get("user_id")
            oid = tok.get("organization_id")
            if not isinstance(uid, str) or not uid or not isinstance(oid, str) or not oid:
                continue
            u = next((r for r in identities if r.get("id") == uid and r.get("entity_type") == "user" and r.get("status") == "active"), None)
            o = next((r for r in identities if r.get("id") == oid and r.get("entity_type") == "organization" and r.get("status") == "active"), None)
            if not u or not o:
                continue
            m = next((r for r in identities if r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("user_id") == uid and r.get("organization_id") == oid), None)
            if not m:
                continue
            exp = tok.get("expires_at")
            if isinstance(exp, str) and exp:
                exp_dt = _parse_dt(exp)
                if exp_dt is not None and exp_dt <= datetime.datetime.utcnow():
                    continue
            return tok, identities
        return None, identities

    if not isinstance(organization_id, str) or re.match(r"^yunx_idn_01J[a-zA-Z0-9]+$", organization_id) is None:
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid organization_id")
        return _err("VALIDATION_ERROR", "Invalid organization_id", organization_id=organization_id)
    if not isinstance(pipeline_id, str) or re.match(r"^yunx_pip_01J[a-zA-Z0-9]+$", pipeline_id) is None:
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid pipeline_id")
        return _err("VALIDATION_ERROR", "Invalid pipeline_id", pipeline_id=pipeline_id)
    if parameters is not None and not isinstance(parameters, dict):
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "parameters must be an object")
        return _err("VALIDATION_ERROR", "parameters must be an object")

    token_row, identities = _resolve_token_context()
    if token_row is None:
        _log(None, "error", "UNAUTHORIZED", "Token is missing or invalid")
        return _err("UNAUTHORIZED", "Token is missing or invalid")
    if token_row.get("organization_id") != organization_id:
        _log(token_row, "error", "UNAUTHORIZED", "Token not authorized for this organization")
        return _err("UNAUTHORIZED", "Token is not permitted to run pipelines in this organization")

    pipelines = _load("pipelines.json")
    if not isinstance(pipelines, list):
        pipelines = []

    pipe = next((r for r in pipelines if r.get("entity_type") == "pipeline" and r.get("id") == pipeline_id and r.get("organization_id") == organization_id and r.get("status") != "deleted"), None)
    if pipe is None:
        _log(token_row, "error", "NOT_FOUND", "Pipeline not found")
        return _err("NOT_FOUND", "Pipeline not found", pipeline_id=pipeline_id, organization_id=organization_id)
    if pipe.get("status") == "disabled":
        _log(token_row, "error", "CONFLICT", "Pipeline is disabled")
        return _err("CONFLICT", "Pipeline is disabled", pipeline_id=pipeline_id)

    # run_number = max+1 per pipeline_id
    runs = [r for r in pipelines if r.get("entity_type") == "pipeline_run" and r.get("pipeline_id") == pipeline_id and r.get("status") != "deleted"]
    max_run = 0
    for r in runs:
        rn = r.get("run_number")
        if isinstance(rn, int) and rn > max_run:
            max_run = rn
    run_number = max_run + 1
    if run_number < 1:
        run_number = 1

    now = _now()
    run = {
        "id": _new_id("yunx_pip_"),
        "entity_type": "pipeline_run",
        "status": "queued",
        "organization_id": organization_id,
        "pipeline_id": pipeline_id,
        "run_number": run_number,
        "triggered_by_user_id": token_row.get("user_id"),
        "parameters": parameters if isinstance(parameters, dict) else None,
        "started_at": None,
        "finished_at": None,
        "duration_seconds": None,
        "created_at": now,
        "updated_at": now,
    }
    # uniqueness (pipeline_id, run_number)
    if any(r.get("entity_type") == "pipeline_run" and r.get("pipeline_id") == pipeline_id and r.get("run_number") == run_number for r in pipelines):
        _log(token_row, "error", "CONFLICT", "Run number conflict")
        return _err("CONFLICT", "Run number conflict; retry", pipeline_id=pipeline_id, run_number=run_number)

    pipelines.append(run)
    _save("pipelines.json", pipelines)

    for r in identities:
        if r.get("id") == token_row.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now
            break
    _save("identity.json", identities)

    _log(token_row, "ok")
    return {"pipeline_run": run}

def get_latest_pipeline_run(organization_id, pipeline_id, status=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_latest_pipeline_run"
    t0 = time.time()

    VALID_STATUS = {"queued", "running", "succeeded", "failed", "canceled", "skipped"}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _ensure_request_log():
        p = os.path.join(_DB, "request_log.json")
        if not os.path.exists(p):
            _save("request_log.json", [])
            return []
        d = _load("request_log.json")
        if not isinstance(d, list):
            _save("request_log.json", [])
            return []
        return d

    def _log(token_row, status_txt, error_code=None, message=None, extra=None):
        logs = _ensure_request_log()
        row = {
            "id": "yunx_req_" + hashlib.sha1(f"{endpoint}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status_txt,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "token_id": token_row.get("id") if isinstance(token_row, dict) else None,
            "organization_id": token_row.get("organization_id") if isinstance(token_row, dict) else None,
            "user_id": token_row.get("user_id") if isinstance(token_row, dict) else None,
            "request": {"organization_id": organization_id, "pipeline_id": pipeline_id, "status": status},
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    def _resolve_token_context():
        identities = _load("identity.json")
        if not isinstance(identities, list):
            identities = []
        for tok in identities:
            if tok.get("entity_type") != "api_token" or tok.get("status") != "active":
                continue
            uid = tok.get("user_id")
            oid = tok.get("organization_id")
            if not isinstance(uid, str) or not uid or not isinstance(oid, str) or not oid:
                continue
            u = next((r for r in identities if r.get("id") == uid and r.get("entity_type") == "user" and r.get("status") == "active"), None)
            o = next((r for r in identities if r.get("id") == oid and r.get("entity_type") == "organization" and r.get("status") == "active"), None)
            if not u or not o:
                continue
            m = next((r for r in identities if r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("user_id") == uid and r.get("organization_id") == oid), None)
            if not m:
                continue
            exp = tok.get("expires_at")
            if isinstance(exp, str) and exp:
                exp_dt = _parse_dt(exp)
                if exp_dt is not None and exp_dt <= datetime.datetime.utcnow():
                    continue
            return tok, identities
        return None, identities

    if not isinstance(organization_id, str) or re.match(r"^yunx_idn_01J[a-zA-Z0-9]+$", organization_id) is None:
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid organization_id")
        return _err("VALIDATION_ERROR", "Invalid organization_id", organization_id=organization_id)
    if not isinstance(pipeline_id, str) or re.match(r"^yunx_pip_01J[a-zA-Z0-9]+$", pipeline_id) is None:
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid pipeline_id")
        return _err("VALIDATION_ERROR", "Invalid pipeline_id", pipeline_id=pipeline_id)
    if status is not None and status not in VALID_STATUS:
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid status")
        return _err("VALIDATION_ERROR", "Invalid status", status=status)

    token_row, identities = _resolve_token_context()
    if token_row is None:
        _log(None, "error", "UNAUTHORIZED", "Token is missing or invalid")
        return _err("UNAUTHORIZED", "Token is missing or invalid")
    if token_row.get("organization_id") != organization_id:
        _log(token_row, "error", "UNAUTHORIZED", "Token not authorized for this organization")
        return _err("UNAUTHORIZED", "Token is not permitted to view pipelines in this organization")

    pipelines = _load("pipelines.json")
    if not isinstance(pipelines, list):
        pipelines = []
    pipe = next((r for r in pipelines if r.get("entity_type") == "pipeline" and r.get("id") == pipeline_id and r.get("organization_id") == organization_id and r.get("status") != "deleted"), None)
    if pipe is None:
        _log(token_row, "error", "NOT_FOUND", "Pipeline not found")
        return _err("NOT_FOUND", "Pipeline not found", pipeline_id=pipeline_id, organization_id=organization_id)

    runs = [r for r in pipelines if r.get("entity_type") == "pipeline_run" and r.get("pipeline_id") == pipeline_id and r.get("organization_id") == organization_id and r.get("status") != "deleted"]
    if status is not None:
        runs = [r for r in runs if r.get("status") == status]

    if not runs:
        _log(token_row, "error", "NOT_FOUND", "No matching pipeline runs")
        return _err("NOT_FOUND", "No qualifying pipeline runs exist", pipeline_id=pipeline_id, status=status)

    def _run_key(r):
        rn = r.get("run_number")
        if isinstance(rn, int):
            return (1, rn, r.get("created_at") or "")
        return (0, 0, r.get("created_at") or "")

    latest = sorted(runs, key=_run_key, reverse=True)[0]

    now = _now()
    for r in identities:
        if r.get("id") == token_row.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now
            break
    _save("identity.json", identities)

    _log(token_row, "ok")
    return {"pipeline_run": latest}

def get_pipeline_run(organization_id, pipeline_run_id, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _id_ok(v, pat):
        return isinstance(v, str) and re.match(pat, v) is not None

    def _record_request(endpoint, org_id, cred_id, status_code, error_code=None, message=None, extra=None, started=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        latency_ms = None
        if started is not None:
            latency_ms = int((time.time() - started) * 1000)
        row = {
            "id": "yunx_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "timestamp": ts,
            "endpoint": endpoint,
            "organization_id": org_id,
            "credential_id": cred_id,
            "status": status_code,
            "latency_ms": latency_ms,
        }
        if error_code:
            row["error_code"] = error_code
        if message:
            row["message"] = message
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _authorize_for_org(request_org_id):
        identities = _load("identity.json")
        if not isinstance(identities, list):
            identities = []
        for tok in identities:
            if tok.get("entity_type") != "api_token" or tok.get("status") != "active":
                continue
            if tok.get("organization_id") != request_org_id:
                continue
            if not tok.get("user_id") or not tok.get("organization_id"):
                continue
            user = next((r for r in identities if r.get("id") == tok.get("user_id") and r.get("entity_type") == "user" and r.get("status") != "deleted"), None)
            org = next((r for r in identities if r.get("id") == tok.get("organization_id") and r.get("entity_type") == "organization" and r.get("status") != "deleted"), None)
            if user and org:
                return {"token": tok, "user": user, "org": org}
        return None

    started = time.time()
    endpoint = "get_pipeline_run"

    if not _id_ok(organization_id, r"^yunx_idn_01J[a-zA-Z0-9]+$"):
        _record_request(endpoint, organization_id, None, 400, "VALIDATION_ERROR", "Invalid organization_id format", started=started)
        return _err("VALIDATION_ERROR", "Invalid organization_id format")
    if not _id_ok(pipeline_run_id, r"^yunx_pip_01J[a-zA-Z0-9]+$"):
        _record_request(endpoint, organization_id, None, 400, "VALIDATION_ERROR", "Invalid pipeline_run_id format", started=started)
        return _err("VALIDATION_ERROR", "Invalid pipeline_run_id format")

    auth = _authorize_for_org(organization_id)
    if not auth:
        _record_request(endpoint, organization_id, None, 401, "UNAUTHORIZED", "No active api_token available for this organization", started=started)
        return _err("UNAUTHORIZED", "Not authorized for this organization")

    pipelines = _load("pipelines.json")
    if not isinstance(pipelines, list):
        pipelines = []

    run = next((r for r in pipelines if r.get("id") == pipeline_run_id and r.get("entity_type") == "pipeline_run" and r.get("organization_id") == organization_id and r.get("status") != "deleted"), None)
    if not run:
        _record_request(endpoint, organization_id, auth["token"].get("id"), 404, "NOT_FOUND", "Pipeline run not found", started=started)
        return _err("NOT_FOUND", "Pipeline run not found")

    # ensure parent pipeline exists under org (guard against orphaned runs)
    pid = run.get("pipeline_id")
    if pid:
        parent = next((r for r in pipelines if r.get("id") == pid and r.get("entity_type") == "pipeline" and r.get("organization_id") == organization_id and r.get("status") != "deleted"), None)
        if not parent:
            _record_request(endpoint, organization_id, auth["token"].get("id"), 404, "NOT_FOUND", "Parent pipeline not found", started=started)
            return _err("NOT_FOUND", "Parent pipeline not found")

    identities = _load("identity.json")
    if isinstance(identities, list):
        changed = False
        for row in identities:
            if row.get("id") == auth["token"].get("id"):
                row["last_used_at"] = _now()
                row["updated_at"] = row.get("updated_at") or row.get("created_at") or _now()
                changed = True
                break
        if changed:
            _save("identity.json", identities)

    _record_request(endpoint, organization_id, auth["token"].get("id"), 200, started=started)
    return {"pipeline_run": run}

