            _record_request(endpoint, organization_id, None, 400, "VALIDATION_ERROR", "run_number must be an integer >= 1", started=started_ts)
            return _err("VALIDATION_ERROR", "run_number must be an integer >= 1")

    sa = _parse_dt(started_after) if started_after is not None else None
    if started_after is not None and sa is None:
        _record_request(endpoint, organization_id, None, 400, "VALIDATION_ERROR", "started_after must be RFC3339 date-time", started=started_ts)
        return _err("VALIDATION_ERROR", "started_after must be RFC3339 date-time")
    sb = _parse_dt(started_before) if started_before is not None else None
    if started_before is not None and sb is None:
        _record_request(endpoint, organization_id, None, 400, "VALIDATION_ERROR", "started_before must be RFC3339 date-time", started=started_ts)
        return _err("VALIDATION_ERROR", "started_before must be RFC3339 date-time")
    if sa and sb and sa > sb:
        _record_request(endpoint, organization_id, None, 400, "VALIDATION_ERROR", "started_after must be <= started_before", started=started_ts)
        return _err("VALIDATION_ERROR", "started_after must be <= started_before")

