            return _parse_dt(r.get("started_at")) or _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, datetime.timezone.utc)
        runs = [r for r in runs if _started_dt2(r) < sb]

    total = len(runs)

    def _sort_key(r):
        if sort_by == "run_number":
            rn = r.get("run_number")
            return rn if isinstance(rn, int) else -1
        if sort_by == "started_at":
            return _parse_dt(r.get("started_at")) or _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, datetime.timezone.utc)
        return _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, datetime.timezone.utc)

    reverse = (sort_order == "desc")
    try:
        runs_sorted = sorted(runs, key=_sort_key, reverse=reverse)
    except TypeError:
        # mixed incomparable types fallback
        runs_sorted = sorted(runs, key=lambda r: str(_sort_key(r)), reverse=reverse)

    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("ascii") + b"===")
            off = int(raw.decode("utf-8"))
            if off < 0:
                raise ValueError
            offset = off
        except Exception:
            _record_request(endpoint, organization_id, auth["token"].get("id"), 400, "VALIDATION_ERROR", "Invalid cursor", started=started_ts)
            return _err("VALIDATION_ERROR", "Invalid cursor")

    page = runs_sorted[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(runs_sorted)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("ascii").rstrip("=")

    # update token last_used_at
    identities = auth.get("identities")
    if isinstance(identities, list):
        changed = False
        for row in identities:
            if row.get("id") == auth["token"].get("id"):
                row["last_used_at"] = _now()
                row["updated_at"] = row.get("updated_at") or row.get("created_at") or _now()
                changed = True
                break
        if changed:
            _save("identity.json", identities)

    _record_request(endpoint, organization_id, auth["token"].get("id"), 200, started=started_ts)
    return {
        "pipeline_runs": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order,
        },
    }

def list_pipeline_jobs_by_category(organization_id, pipeline_run_id, category, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _id_ok(v, pat):
        return isinstance(v, str) and re.match(pat, v) is not None

    def _record_request(endpoint, org_id, cred_id, status_code, error_code=None, message=None, extra=None, started=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        latency_ms = None
        if started is not None:
            latency_ms = int((time.time() - started) * 1000)
        row = {
            "id": "yunx_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "timestamp": ts,
            "endpoint": endpoint,
            "organization_id": org_id,
            "credential_id": cred_id,
            "status": status_code,
            "latency_ms": latency_ms,
        }
        if error_code:
            row["error_code"] = error_code
        if message:
            row["message"] = message
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _authorize_for_org(request_org_id):
        identities = _load("identity.json")
        if not isinstance(identities, list):
            identities = []
        for tok in identities:
            if tok.get("entity_type") != "api_token" or tok.get("status") != "active":
                continue
            if tok.get("organization_id") != request_org_id:
                continue
            if not tok.get("user_id") or not tok.get("organization_id"):
                continue
            user = next((r for r in identities if r.get("id") == tok.get("user_id") and r.get("entity_type") == "user" and r.get("status") != "deleted"), None)
            org = next((r for r in identities if r.get("id") == tok.get("organization_id") and r.get("entity_type") == "organization" and r.get("status") != "deleted"), None)
            if user and org:
                return {"token": tok, "user": user, "org": org, "identities": identities}
        return None

    started = time.time()
    endpoint = "list_pipeline_jobs_by_category"

    if limit is None:
        limit = 50

    # validate
    if not _id_ok(organization_id, r"^yunx_idn_01J[a-zA-Z0-9]+$"):
        _record_request(endpoint, organization_id, None, 400, "VALIDATION_ERROR", "Invalid organization_id format", started=started)
        return _err("VALIDATION_ERROR", "Invalid organization_id format")
    if not _id_ok(pipeline_run_id, r"^yunx_pip_01J[a-zA-Z0-9]+$"):
        _record_request(endpoint, organization_id, None, 400, "VALIDATION_ERROR", "Invalid pipeline_run_id format", started=started)
        return _err("VALIDATION_ERROR", "Invalid pipeline_run_id format")
    if category != "DEPLOY":
        _record_request(endpoint, organization_id, None, 400, "VALIDATION_ERROR", "Only category='DEPLOY' is supported", started=started)
        return _err("VALIDATION_ERROR", "Only category='DEPLOY' is supported")
    allowed_status = {"queued", "running", "succeeded", "failed", "canceled", "skipped"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _record_request(endpoint, organization_id, None, 400, "VALIDATION_ERROR", "Invalid status value", started=started)
            return _err("VALIDATION_ERROR", "Invalid status value")
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _record_request(endpoint, organization_id, None, 400, "VALIDATION_ERROR", "limit must be between 1 and 200", started=started)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _record_request(endpoint, organization_id, None, 400, "VALIDATION_ERROR", "cursor must be a string", started=started)
        return _err("VALIDATION_ERROR", "cursor must be a string")

    auth = _authorize_for_org(organization_id)
    if not auth:
        _record_request(endpoint, organization_id, None, 401, "UNAUTHORIZED", "No active api_token available for this organization", started=started)
        return _err("UNAUTHORIZED", "Not authorized for this organization")

    pipelines = _load("pipelines.json")
    if not isinstance(pipelines, list):
        pipelines = []

    run = next((r for r in pipelines if r.get("id") == pipeline_run_id and r.get("entity_type") == "pipeline_run" and r.get("organization_id") == organization_id and r.get("status") != "deleted"), None)
    if not run:
        _record_request(endpoint, organization_id, auth["token"].get("id"), 404, "NOT_FOUND", "Pipeline run not found", started=started)
        return _err("NOT_FOUND", "Pipeline run not found")

    # list pipeline_job_run rows for the run; join to pipeline_job to filter by category
    job_templates = {r.get("id"): r for r in pipelines if r.get("entity_type") == "pipeline_job" and r.get("organization_id") == organization_id and r.get("status") != "deleted"}
    job_runs = [r for r in pipelines if r.get("entity_type") == "pipeline_job_run" and r.get("pipeline_run_id") == pipeline_run_id and r.get("organization_id") == organization_id and r.get("status") != "deleted"]

    filtered = []
    for jr in job_runs:
        jt = job_templates.get(jr.get("pipeline_job_id"))
        if not jt:
            continue
        if jt.get("category") != category:
            continue
        if status is not None and jr.get("status") != status:
            continue
        # return a combined view similar to common APIs: job_run + job template fields
        out = dict(jr)
        out["job"] = {"id": jt.get("id"), "name": jt.get("name"), "category": jt.get("category"), "pipeline_id": jt.get("pipeline_id")}
        filtered.append(out)

    total = len(filtered)
    # order by created_at desc (history-like)
    def _created_dt(r):
        s = r.get("created_at")
        if isinstance(s, str):
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(ss)
            except Exception:
                pass
        return datetime.datetime.fromtimestamp(0, datetime.timezone.utc)

    filtered_sorted = sorted(filtered, key=_created_dt, reverse=True)

    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("ascii") + b"===")
            off = int(raw.decode("utf-8"))
            if off < 0:
                raise ValueError
            offset = off
        except Exception:
            _record_request(endpoint, organization_id, auth["token"].get("id"), 400, "VALIDATION_ERROR", "Invalid cursor", started=started)
            return _err("VALIDATION_ERROR", "Invalid cursor")

    page = filtered_sorted[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(filtered_sorted)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("ascii").rstrip("=")

    identities = auth.get("identities")
    if isinstance(identities, list):
        changed = False
        for row in identities:
            if row.get("id") == auth["token"].get("id"):
                row["last_used_at"] = _now()
                row["updated_at"] = row.get("updated_at") or row.get("created_at") or _now()
                changed = True
                break
        if changed:
            _save("identity.json", identities)

    _record_request(endpoint, organization_id, auth["token"].get("id"), 200, started=started)
    return {
        "jobs": page,
        "meta": {"total": total, "limit": limit, "cursor": cursor, "has_more": has_more, "next_cursor": next_cursor},
    }

def list_pipeline_job_historys(pipeline_job_id, status=None, cursor=None, limit=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _dt_key(row, field):
        dt = _parse_dt(row.get(field))
        if dt is None:
            dt = _parse_dt(row.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt

    def _gen_cursor(sort_value_dt, row_id):
        payload = {
            "v": int(sort_value_dt.timestamp() * 1000),
            "id": row_id
        }
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _parse_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return "bad"
        s = cur.strip()
        pad = "=" * (-len(s) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return "bad"
            v = obj.get("v")
            rid = obj.get("id")
            if not isinstance(v, int) or not isinstance(rid, str) or not rid:
                return "bad"
            return obj
        except Exception:
            return "bad"

    # ---- auth (ambient): choose any active api_token that maps to active user+org and has membership ----
    identities = _load("identity.json")
    pipelines = _load("pipelines.json")

    token_row = None
    token_user = None
    token_org = None
    for t in identities:
        if t.get("entity_type") != "api_token" or t.get("status") != "active":
            continue
        uid = t.get("user_id")
        oid = t.get("organization_id")
        if not isinstance(uid, str) or not isinstance(oid, str) or not uid or not oid:
            continue
        u = next((r for r in identities if r.get("id") == uid and r.get("entity_type") == "user" and r.get("status") == "active"), None)
        o = next((r for r in identities if r.get("id") == oid and r.get("entity_type") == "organization" and r.get("status") == "active"), None)
        if not u or not o:
            continue
        m = next((r for r in identities if r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("user_id") == uid and r.get("organization_id") == oid), None)
        if not m:
            continue
        token_row, token_user, token_org = t, u, o
        break

    # request log / quota+rate handling if collection exists
    usage = _load("usage.json")
    if isinstance(usage, list):
        now = datetime.datetime.now(datetime.timezone.utc)
        window = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in usage:
            if r.get("endpoint") != "list_pipeline_job_historys":
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts and ts >= window:
                recent += 1
        if recent >= 120:
            usage.append({
                "id": f"usage_{int(time.time()*1000)}",
                "endpoint": "list_pipeline_job_historys",
                "credential_id": token_row.get("id") if token_row else None,
                "status": "RATE_LIMIT",
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _now_iso(),
            })
            _save("usage.json", usage)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
    if not token_row:
        if isinstance(usage, list):
            usage.append({
                "id": f"usage_{int(time.time()*1000)}",
                "endpoint": "list_pipeline_job_historys",
                "credential_id": None,
                "status": "UNAUTHORIZED",
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _now_iso(),
            })
            _save("usage.json", usage)
        return _err("UNAUTHORIZED", "Missing or invalid API token.")

    # ---- validate inputs ----
    if not isinstance(pipeline_job_id, str) or not re.match(r"^yunx_pip_01J[0-9A-Z]+$", pipeline_job_id):
        if isinstance(usage, list):
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_pipeline_job_historys", "credential_id": token_row.get("id"), "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
        return _err("VALIDATION_ERROR", "pipeline_job_id is malformed.")
    allowed_status = {"queued", "running", "succeeded", "failed", "canceled", "skipped"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        if isinstance(usage, list):
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_pipeline_job_historys", "credential_id": token_row.get("id"), "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
        return _err("VALIDATION_ERROR", "Unsupported status filter.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        if isinstance(usage, list):
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_pipeline_job_historys", "credential_id": token_row.get("id"), "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
        return _err("VALIDATION_ERROR", "limit out of bounds.")
    if sort_by is None:
        sort_by = "created_at"
    if sort_order is None:
        sort_order = "desc"
    if sort_by not in {"started_at", "created_at"}:
        if isinstance(usage, list):
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_pipeline_job_historys", "credential_id": token_row.get("id"), "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
        return _err("VALIDATION_ERROR", "Unsupported sort_by.")
    if sort_order not in {"asc", "desc"}:
        if isinstance(usage, list):
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_pipeline_job_historys", "credential_id": token_row.get("id"), "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
        return _err("VALIDATION_ERROR", "Unsupported sort_order.")
    cur_obj = _parse_cursor(cursor)
    if cur_obj == "bad":
        if isinstance(usage, list):
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_pipeline_job_historys", "credential_id": token_row.get("id"), "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    # ---- access control ----
    job = next((r for r in pipelines if r.get("id") == pipeline_job_id and r.get("entity_type") == "pipeline_job"), None)
    if not job or job.get("status") == "deleted":
        if isinstance(usage, list):
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_pipeline_job_historys", "credential_id": token_row.get("id"), "status": "NOT_FOUND", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
        return _err("NOT_FOUND", "Pipeline job not found.")
    if job.get("organization_id") != token_org.get("id"):
        if isinstance(usage, list):
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_pipeline_job_historys", "credential_id": token_row.get("id"), "status": "UNAUTHORIZED", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
        return _err("UNAUTHORIZED", "Not authorized to access this pipeline job.")

    # ---- query ----
    runs = [r for r in pipelines if r.get("entity_type") == "pipeline_job_run" and r.get("pipeline_job_id") == pipeline_job_id and r.get("organization_id") == token_org.get("id")]
    if status is not None:
        runs = [r for r in runs if r.get("status") == status]

    reverse = (sort_order == "desc")
    runs.sort(key=lambda rr: (_dt_key(rr, sort_by), rr.get("id") or ""), reverse=reverse)

    # cursor filtering (keyset)
    if cur_obj:
        cur_dt = datetime.datetime.fromtimestamp(cur_obj["v"] / 1000.0, tz=datetime.timezone.utc)
        cur_id = cur_obj["id"]

        def _after(rr):
            kdt = _dt_key(rr, sort_by)
            rid = rr.get("id") or ""
            if reverse:
                # descending: next page contains items with (kdt, id) < (cur_dt, cur_id)
                return (kdt < cur_dt) or (kdt == cur_dt and rid < cur_id)
            else:
                return (kdt > cur_dt) or (kdt == cur_dt and rid > cur_id)

        runs = [r for r in runs if _after(r)]

    page = runs[:limit]
    has_more = len(runs) > len(page)
    next_cursor = None
    if page:
        last = page[-1]
        next_cursor = _gen_cursor(_dt_key(last, sort_by), last.get("id") or "")

    resp = {
        "data": page,
        "meta": {
            "total": len(runs) if cursor is None else None,
            "limit": limit,
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }

    if isinstance(usage, list):
        usage.append({
            "id": f"usage_{int(time.time()*1000)}",
            "endpoint": "list_pipeline_job_historys",
            "credential_id": token_row.get("id"),
            "status": "OK",
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save("usage.json", usage)

    return resp

def execute_pipeline_job_run(pipeline_run_id, pipeline_job_id, parameters=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "execute_pipeline_job_run"
    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _new_id(prefix):
        return prefix + hashlib.sha1(f"{prefix}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:18].upper()

    def _ensure_request_log():
        p = os.path.join(_DB, "request_log.json")
        if not os.path.exists(p):
            _save("request_log.json", [])
            return []
        d = _load("request_log.json")
        if not isinstance(d, list):
            _save("request_log.json", [])
            return []
        return d

    def _log(token_row, status, error_code=None, message=None, extra=None):
        logs = _ensure_request_log()
        row = {
            "id": "yunx_req_" + hashlib.sha1(f"{endpoint}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "token_id": token_row.get("id") if isinstance(token_row, dict) else None,
            "organization_id": token_row.get("organization_id") if isinstance(token_row, dict) else None,
            "user_id": token_row.get("user_id") if isinstance(token_row, dict) else None,
            "request": {"pipeline_run_id": pipeline_run_id, "pipeline_job_id": pipeline_job_id},
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    def _resolve_token_context():
        identities = _load("identity.json")
        if not isinstance(identities, list):
            identities = []
        for tok in identities:
            if tok.get("entity_type") != "api_token" or tok.get("status") != "active":
                continue
            uid = tok.get("user_id")
            oid = tok.get("organization_id")
            if not isinstance(uid, str) or not uid or not isinstance(oid, str) or not oid:
                continue
            u = next((r for r in identities if r.get("id") == uid and r.get("entity_type") == "user" and r.get("status") == "active"), None)
            o = next((r for r in identities if r.get("id") == oid and r.get("entity_type") == "organization" and r.get("status") == "active"), None)
            if not u or not o:
                continue
            m = next((r for r in identities if r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("user_id") == uid and r.get("organization_id") == oid), None)
            if not m:
                continue
            exp = tok.get("expires_at")
            if isinstance(exp, str) and exp:
                exp_dt = _parse_dt(exp)
                if exp_dt is not None and exp_dt <= datetime.datetime.utcnow():
                    continue
            return tok, identities
        return None, identities

    if not isinstance(pipeline_run_id, str) or re.match(r"^yunx_pip_01J[0-9A-Z]+$", pipeline_run_id) is None:
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid pipeline_run_id")
        return _err("VALIDATION_ERROR", "Invalid pipeline_run_id", pipeline_run_id=pipeline_run_id)
    if not isinstance(pipeline_job_id, str) or re.match(r"^yunx_pip_01J[0-9A-Z]+$", pipeline_job_id) is None:
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid pipeline_job_id")
        return _err("VALIDATION_ERROR", "Invalid pipeline_job_id", pipeline_job_id=pipeline_job_id)
    if parameters is not None and not isinstance(parameters, dict):
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "parameters must be an object")
        return _err("VALIDATION_ERROR", "parameters must be an object")

    token_row, identities = _resolve_token_context()
    if token_row is None:
        _log(None, "error", "UNAUTHORIZED", "Token is missing or invalid")
        return _err("UNAUTHORIZED", "Token is missing or invalid")

    pipelines = _load("pipelines.json")
    if not isinstance(pipelines, list):
        pipelines = []

    run = next((r for r in pipelines if r.get("entity_type") == "pipeline_run" and r.get("id") == pipeline_run_id and r.get("status") != "deleted"), None)
    if run is None:
        _log(token_row, "error", "NOT_FOUND", "Pipeline run not found")
        return _err("NOT_FOUND", "Pipeline run not found", pipeline_run_id=pipeline_run_id)
    job = next((r for r in pipelines if r.get("entity_type") == "pipeline_job" and r.get("id") == pipeline_job_id and r.get("status") != "deleted"), None)
    if job is None:
        _log(token_row, "error", "NOT_FOUND", "Pipeline job not found")
        return _err("NOT_FOUND", "Pipeline job not found", pipeline_job_id=pipeline_job_id)

    # org visibility
    if run.get("organization_id") != token_row.get("organization_id") or job.get("organization_id") != token_row.get("organization_id"):
        _log(token_row, "error", "UNAUTHORIZED", "Token not authorized for this job/run")
        return _err("UNAUTHORIZED", "Token is not permitted to execute this pipeline job run")

    # must link to existing pipeline_run and pipeline_job; and same pipeline
    if run.get("pipeline_id") != job.get("pipeline_id"):
        _log(token_row, "error", "CONFLICT", "Job does not belong to the run's pipeline")
        return _err("CONFLICT", "pipeline_job_id does not belong to the pipeline of pipeline_run_id")

    # disallowed if parent run completed/canceled
    if run.get("status") in ("succeeded", "failed", "canceled"):
        _log(token_row, "error", "CONFLICT", "Cannot start job run for completed pipeline run")
        return _err("CONFLICT", "Cannot start a job run because the pipeline run is completed/canceled", pipeline_run_status=run.get("status"))

    now = _now()
    job_run = {
        "id": _new_id("yunx_pip_"),
        "entity_type": "pipeline_job_run",
        "status": "queued",
        "organization_id": run.get("organization_id"),
        "pipeline_id": run.get("pipeline_id"),
        "pipeline_run_id": pipeline_run_id,
        "pipeline_job_id": pipeline_job_id,
        "triggered_by_user_id": token_row.get("user_id"),
        "parameters": parameters if isinstance(parameters, dict) else None,
        "started_at": None,
        "finished_at": None,
        "duration_seconds": None,
        "created_at": now,
        "updated_at": now,
    }
    pipelines.append(job_run)
    _save("pipelines.json", pipelines)

    for r in identities:
        if r.get("id") == token_row.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now
            break
    _save("identity.json", identities)

    _log(token_row, "ok")
    return {"pipeline_job_run": job_run}

def get_pipeline_job_run_log(pipeline_job_run_id, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_pipeline_job_run_log"
    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _ensure_request_log():
        p = os.path.join(_DB, "request_log.json")
        if not os.path.exists(p):
            _save("request_log.json", [])
            return []
        d = _load("request_log.json")
        if not isinstance(d, list):
            _save("request_log.json", [])
            return []
        return d

    def _log(token_row, status, error_code=None, message=None, extra=None):
        logs = _ensure_request_log()
        row = {
            "id": "yunx_req_" + hashlib.sha1(f"{endpoint}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "token_id": token_row.get("id") if isinstance(token_row, dict) else None,
            "organization_id": token_row.get("organization_id") if isinstance(token_row, dict) else None,
            "user_id": token_row.get("user_id") if isinstance(token_row, dict) else None,
            "request": {"pipeline_job_run_id": pipeline_job_run_id},
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    def _resolve_token_context():
        identities = _load("identity.json")
        if not isinstance(identities, list):
            identities = []
        for tok in identities:
            if tok.get("entity_type") != "api_token" or tok.get("status") != "active":
                continue
            uid = tok.get("user_id")
            oid = tok.get("organization_id")
            if not isinstance(uid, str) or not uid or not isinstance(oid, str) or not oid:
                continue
            u = next((r for r in identities if r.get("id") == uid and r.get("entity_type") == "user" and r.get("status") == "active"), None)
            o = next((r for r in identities if r.get("id") == oid and r.get("entity_type") == "organization" and r.get("status") == "active"), None)
            if not u or not o:
                continue
            m = next((r for r in identities if r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("user_id") == uid and r.get("organization_id") == oid), None)
            if not m:
                continue
            exp = tok.get("expires_at")
            if isinstance(exp, str) and exp:
                exp_dt = _parse_dt(exp)
                if exp_dt is not None and exp_dt <= datetime.datetime.utcnow():
                    continue
            return tok, identities
        return None, identities

    if not isinstance(pipeline_job_run_id, str) or re.match(r"^yunx_pip_01J[0-9A-Z]+$", pipeline_job_run_id) is None:
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid pipeline_job_run_id")
        return _err("VALIDATION_ERROR", "Invalid pipeline_job_run_id", pipeline_job_run_id=pipeline_job_run_id)

    token_row, identities = _resolve_token_context()
    if token_row is None:
        _log(None, "error", "UNAUTHORIZED", "Token is missing or invalid")
        return _err("UNAUTHORIZED", "Token is missing or invalid")

    pipelines = _load("pipelines.json")
    if not isinstance(pipelines, list):
        pipelines = []

    jr = next((r for r in pipelines if r.get("entity_type") == "pipeline_job_run" and r.get("id") == pipeline_job_run_id and r.get("status") != "deleted"), None)
    if jr is None:
        _log(token_row, "error", "NOT_FOUND", "Pipeline job run not found")
        return _err("NOT_FOUND", "pipeline_job_run_id does not exist", pipeline_job_run_id=pipeline_job_run_id)

    if jr.get("organization_id") != token_row.get("organization_id"):
        _log(token_row, "error", "UNAUTHORIZED", "Token not authorized for this job run log")
        return _err("UNAUTHORIZED", "Token is not permitted to access this job run logs")

    logs = [r for r in pipelines if r.get("entity_type") == "pipeline_job_log" and r.get("pipeline_run_id") == jr.get("pipeline_run_id") and r.get("status") != "deleted" and r.get("pipeline_job_id") == jr.get("pipeline_job_id")]
    # newest by created_at
    logs.sort(key=lambda r: r.get("created_at") or "", reverse=True)
    log_row = logs[0] if logs else None
    if log_row is None:
        # if run hasn't started yet, logs may not be available
        if jr.get("status") in ("queued", "skipped"):
            _log(token_row, "error", "CONFLICT", "Logs not available for current job run state")
            return _err("CONFLICT", "Logs are not available for the current job run state", status=jr.get("status"))
        _log(token_row, "error", "NOT_FOUND", "No logs found for this job run")
        return _err("NOT_FOUND", "No logs found for this job run", pipeline_job_run_id=pipeline_job_run_id)

    # validate truncated log: if content looks truncated, require uri
    content = log_row.get("log_content")
    uri = log_row.get("log_uri")
    if isinstance(content, str) and len(content) >= 4000 and not uri:
        # keep data but also indicate missing uri
        pass

    now = _now()
    for r in identities:
        if r.get("id") == token_row.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now
            break
    _save("identity.json", identities)

    _log(token_row, "ok")
    return {"pipeline_job_run": jr, "log": log_row}

def list_package_repositories(repo_type=None, status=None, name=None, cursor=None, limit=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _dt_key(row, field):
        dt = _parse_dt(row.get(field))
        if dt is None:
            dt = _parse_dt(row.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt

    def _gen_cursor(sort_value, row_id):
        payload = {"v": sort_value, "id": row_id}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _parse_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return "bad"
        s = cur.strip()
        pad = "=" * (-len(s) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return "bad"
            if "v" not in obj or "id" not in obj:
                return "bad"
            if not isinstance(obj["id"], str) or not obj["id"]:
                return "bad"
            return obj
        except Exception:
            return "bad"

    identities = _load("identity.json")
    packages = _load("packages.json")

    # ---- auth (ambient) ----
    token_row = None
    token_user = None
    token_org = None
    for t in identities:
        if t.get("entity_type") != "api_token" or t.get("status") != "active":
            continue
        uid = t.get("user_id")
        oid = t.get("organization_id")
        if not isinstance(uid, str) or not isinstance(oid, str) or not uid or not oid:
            continue
        u = next((r for r in identities if r.get("id") == uid and r.get("entity_type") == "user" and r.get("status") == "active"), None)
        o = next((r for r in identities if r.get("id") == oid and r.get("entity_type") == "organization" and r.get("status") == "active"), None)
        if not u or not o:
            continue
        m = next((r for r in identities if r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("user_id") == uid and r.get("organization_id") == oid), None)
        if not m:
            continue
        token_row, token_user, token_org = t, u, o
        break

    usage = _load("usage.json")
    if isinstance(usage, list):
        now = datetime.datetime.now(datetime.timezone.utc)
        window = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in usage:
            if r.get("endpoint") != "list_package_repositories":
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts and ts >= window:
                recent += 1
        if recent >= 120:
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_package_repositories", "credential_id": token_row.get("id") if token_row else None, "status": "RATE_LIMIT", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
    if not token_row:
        if isinstance(usage, list):
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_package_repositories", "credential_id": None, "status": "UNAUTHORIZED", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
        return _err("UNAUTHORIZED", "Missing or invalid API token.")

    # ---- validate inputs ----
    allowed_repo_type = {"maven", "npm", "pypi", "nuget", "docker", "generic"}
    if repo_type is not None and (not isinstance(repo_type, str) or repo_type not in allowed_repo_type):
        if isinstance(usage, list):
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_package_repositories", "credential_id": token_row.get("id"), "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
        return _err("VALIDATION_ERROR", "Unsupported repo_type.")
    allowed_status = {"active", "deleted"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        if isinstance(usage, list):
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_package_repositories", "credential_id": token_row.get("id"), "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
        return _err("VALIDATION_ERROR", "Unsupported status.")
    if name is not None and not isinstance(name, str):
        if isinstance(usage, list):
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_package_repositories", "credential_id": token_row.get("id"), "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
        return _err("VALIDATION_ERROR", "name must be a string.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        if isinstance(usage, list):
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_package_repositories", "credential_id": token_row.get("id"), "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
        return _err("VALIDATION_ERROR", "limit out of bounds.")
    if sort_by is None:
        sort_by = "created_at"
    if sort_order is None:
        sort_order = "desc"
    if sort_by not in {"created_at", "updated_at", "name"}:
        if isinstance(usage, list):
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_package_repositories", "credential_id": token_row.get("id"), "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
        return _err("VALIDATION_ERROR", "Unsupported sort_by.")
    if sort_order not in {"asc", "desc"}:
        if isinstance(usage, list):
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_package_repositories", "credential_id": token_row.get("id"), "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
        return _err("VALIDATION_ERROR", "Unsupported sort_order.")
    cur_obj = _parse_cursor(cursor)
    if cur_obj == "bad":
        if isinstance(usage, list):
            usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_package_repositories", "credential_id": token_row.get("id"), "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-_t0)*1000), "timestamp": _now_iso()})
            _save("usage.json", usage)
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    # ---- query ----
    org_id = token_org.get("id")
    repos = [r for r in packages if r.get("entity_type") == "package_repository" and r.get("organization_id") == org_id]

    if repo_type is not None:
        repos = [r for r in repos if r.get("repo_type") == repo_type]
    if status is not None:
        repos = [r for r in repos if r.get("status") == status]
    if name is not None and name.strip():
        q = name.strip().lower()
        repos = [r for r in repos if isinstance(r.get("name"), str) and q in r.get("name").lower()]

    reverse = (sort_order == "desc")
    if sort_by in ("created_at", "updated_at"):
        repos.sort(key=lambda rr: (_dt_key(rr, sort_by), rr.get("id") or ""), reverse=reverse)
        # keyset cursor uses milliseconds timestamp
        if cur_obj:
            cur_dt = datetime.datetime.fromtimestamp(int(cur_obj["v"]) / 1000.0, tz=datetime.timezone.utc)
            cur_id = cur_obj["id"]

            def _after(rr):
                kdt = _dt_key(rr, sort_by)
                rid = rr.get("id") or ""
                if reverse:
                    return (kdt < cur_dt) or (kdt == cur_dt and rid < cur_id)
                return (kdt > cur_dt) or (kdt == cur_dt and rid > cur_id)

            repos = [r for r in repos if _after(r)]
    else:
        # name sort
        def _nm(rr):
            v = rr.get("name")
            return v.lower() if isinstance(v, str) else ""
        repos.sort(key=lambda rr: (_nm(rr), rr.get("id") or ""), reverse=reverse)
        if cur_obj:
            cur_v = cur_obj["v"]
            cur_id = cur_obj["id"]
            if not isinstance(cur_v, str):
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            cur_v_norm = cur_v.lower()

            def _after(rr):
                v = _nm(rr)
                rid = rr.get("id") or ""
                if reverse:
                    return (v < cur_v_norm) or (v == cur_v_norm and rid < cur_id)
                return (v > cur_v_norm) or (v == cur_v_norm and rid > cur_id)

            repos = [r for r in repos if _after(r)]

    page = repos[:limit]
    has_more = len(repos) > len(page)
    next_cursor = None
    if page:
        last = page[-1]
        if sort_by in ("created_at", "updated_at"):
            next_cursor = _gen_cursor(int(_dt_key(last, sort_by).timestamp() * 1000), last.get("id") or "")
        else:
            next_cursor = _gen_cursor((last.get("name") or ""), last.get("id") or "")

    resp = {
        "data": page,
        "meta": {
            "total": len(repos) if cursor is None else None,
            "limit": limit,
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order,
            "organization_id": org_id
        }
    }

    # token last_used_at update
    now_iso = _now_iso()
    token_row["last_used_at"] = now_iso
    token_row["updated_at"] = now_iso
    for i, r in enumerate(identities):
        if r.get("id") == token_row.get("id"):
            identities[i] = token_row
            break
    _save("identity.json", identities)

    if isinstance(usage, list):
        usage.append({"id": f"usage_{int(time.time()*1000)}", "endpoint": "list_package_repositories", "credential_id": token_row.get("id"), "status": "OK", "latency_ms": int((time.time()-_t0)*1000), "timestamp": now_iso})
        _save("usage.json", usage)

    return resp

def list_artifacts(package_repository_id, status=None, name=None, version=None, cursor=None, limit=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- Validate inputs
    if not isinstance(package_repository_id, str):
        return _err("VALIDATION_ERROR", "package_repository_id must be a string")
    if not re.match(r"^yunx_pkg_01J[0-9A-Z]+$", package_repository_id):
        return _err("VALIDATION_ERROR", "package_repository_id is malformed")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, deleted")
    if name is not None and not isinstance(name, str):
        return _err("VALIDATION_ERROR", "name must be a string")
    if version is not None and not isinstance(version, str):
        return _err("VALIDATION_ERROR", "version must be a string")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if sort_by is None:
        sort_by = "created_at"
    if not isinstance(sort_by, str) or sort_by not in ("created_at", "updated_at", "name", "version"):
        return _err("VALIDATION_ERROR", "sort_by must be one of: created_at, updated_at, name, version")
    if sort_order is None:
        sort_order = "desc"
    if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc")

    # ---- Authorization (ambient): must be an active api_token; choose any valid one
    identities = _load("identity.json")
    token_row = None
    for r in identities:
        if r.get("entity_type") == "api_token" and r.get("status") == "active" and r.get("user_id") and r.get("organization_id"):
            # if expires_at present, ensure not expired
            exp = r.get("expires_at")
            if isinstance(exp, str) and exp:
                try:
                    exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00"))
                    if exp_dt <= datetime.datetime.now(datetime.timezone.utc):
                        continue
                except Exception:
                    pass
            token_row = r
            break

    # Prepare request log collection (create if missing in store; observable dynamics)
    reqlog = _load("request_log.json")
    if not isinstance(reqlog, list):
        reqlog = []

    def _log(status_code, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        req = {
            "id": "req_" + hashlib.sha1((now + str(time.time())).encode("utf-8")).hexdigest()[:16],
            "endpoint": "list_artifacts",
            "timestamp": now,
            "status": status_code,
            "latency_ms": latency_ms,
            "organization_id": token_row.get("organization_id") if token_row else None,
            "user_id": token_row.get("user_id") if token_row else None,
            "api_token_id": token_row.get("id") if token_row else None,
        }
        if error_code:
            req["error_code"] = error_code
        reqlog.append(req)
        _save("request_log.json", reqlog)

    if token_row is None:
        _log(401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid credentials")

    org_id = token_row.get("organization_id")

    # ---- Quota/rate limit enforcement via request_log (simple, but stateful)
    # Rate limit: 120 requests/min per token
    try:
        window_start = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0)
        token_id = token_row.get("id")
        recent = 0
        for r in reqlog:
            if r.get("api_token_id") != token_id:
                continue
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    ts_dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
                    if ts_dt >= window_start:
                        recent += 1
                except Exception:
                    continue
        if recent >= 120:
            _log(429, "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded")
    except Exception:
        # do not crash
        pass

    # ---- Validate repository exists and belongs to org
    packages = _load("packages.json")
    repo_row = None
    for r in packages:
        if r.get("id") == package_repository_id and r.get("entity_type") == "package_repository" and r.get("status") != "deleted":
            repo_row = r
            break
    if repo_row is None or repo_row.get("organization_id") != org_id:
        # "read whose filters match nothing returns empty result set" -> for list, return empty, not NOT_FOUND
        _log(200)
        return {
            "artifacts": [],
            "pagination": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None},
            "sort": {"by": sort_by, "order": sort_order},
        }

    # ---- Filter artifacts
    want_status = status if status is not None else "active"
    nm = name.lower() if isinstance(name, str) else None

    rows = []
    for r in packages:
        if r.get("entity_type") != "artifact":
            continue
        if r.get("package_repository_id") != package_repository_id:
            continue
        # default visibility: active unless explicitly requested
        if status is None:
            if r.get("status") != "active":
                continue
        else:
            if r.get("status") != want_status:
                continue
        if nm is not None:
            rn = r.get("name") or ""
            if nm not in rn.lower():
                continue
        if version is not None:
            if r.get("version") != version:
                continue
        rows.append(r)

    # ---- Sorting
    reverse = (sort_order == "desc")

    def _sort_key(r):
        v = r.get(sort_by)
        if sort_by in ("created_at", "updated_at"):
            if isinstance(v, str):
                return v
            return ""
        if v is None:
            return ""
        return str(v)

    try:
        rows.sort(key=_sort_key, reverse=reverse)
    except Exception:
        # fallback stable sort
        rows = sorted(rows, key=lambda r: (r.get(sort_by) is None, str(r.get(sort_by) or "")), reverse=reverse)

    total = len(rows)

    # ---- Cursor pagination: cursor is base64url encoded integer offset
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            if not raw.startswith("o:"):
                _log(400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid")
            offset = int(raw.split(":", 1)[1])
            if offset < 0 or offset > total:
                _log(400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is out of range")
        except Exception:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid")

    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(("o:%d" % next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    _log(200)
    return {
        "artifacts": page,
        "pagination": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
        "sort": {"by": sort_by, "order": sort_order},
        "package_repository": {"id": repo_row.get("id"), "name": repo_row.get("name"), "repo_type": repo_row.get("repo_type")},
    }

def get_artifact(artifact_id, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_artifact"
    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _ensure_request_log():
        p = os.path.join(_DB, "request_log.json")
        if not os.path.exists(p):
            _save("request_log.json", [])
            return []
        d = _load("request_log.json")
        if not isinstance(d, list):
            _save("request_log.json", [])
            return []
        return d

    def _log(token_row, status, error_code=None, message=None, extra=None):
        logs = _ensure_request_log()
        row = {
            "id": "yunx_req_" + hashlib.sha1(f"{endpoint}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "token_id": token_row.get("id") if isinstance(token_row, dict) else None,
            "organization_id": token_row.get("organization_id") if isinstance(token_row, dict) else None,
            "user_id": token_row.get("user_id") if isinstance(token_row, dict) else None,
            "request": {"artifact_id": artifact_id},
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    def _resolve_token_context():
        identities = _load("identity.json")
        if not isinstance(identities, list):
            identities = []
        for tok in identities:
            if tok.get("entity_type") != "api_token" or tok.get("status") != "active":
                continue
            uid = tok.get("user_id")
            oid = tok.get("organization_id")
            if not isinstance(uid, str) or not uid or not isinstance(oid, str) or not oid:
                continue
            u = next((r for r in identities if r.get("id") == uid and r.get("entity_type") == "user" and r.get("status") == "active"), None)
            o = next((r for r in identities if r.get("id") == oid and r.get("entity_type") == "organization" and r.get("status") == "active"), None)
            if not u or not o:
                continue
            m = next((r for r in identities if r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("user_id") == uid and r.get("organization_id") == oid), None)
            if not m:
                continue
            exp = tok.get("expires_at")
            if isinstance(exp, str) and exp:
                exp_dt = _parse_dt(exp)
                if exp_dt is not None and exp_dt <= datetime.datetime.utcnow():
                    continue
            return tok, identities
        return None, identities

    def _rate_limit_check(token_row):
        if not isinstance(token_row, dict):
            return None
        logs = _ensure_request_log()
        token_id = token_row.get("id")
        if not isinstance(token_id, str) or not token_id:
            return None
        window_sec = 60
        limit = 120
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_sec)
        cnt = 0
        for r in reversed(logs[-5000:]):
            if r.get("token_id") != token_id:
                continue
            dt = _parse_dt(r.get("timestamp"))
            if not dt:
                continue
            if dt >= cutoff:
                cnt += 1
                if cnt >= limit:
                    return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_sec, limit=limit)
        return None

    if not isinstance(artifact_id, str) or re.match(r"^yunx_pkg_01J[0-9A-Z]+$", artifact_id) is None:
        tok, _ids = _resolve_token_context()
        _log(tok, "error", "VALIDATION_ERROR", "Invalid artifact_id")
        return _err("VALIDATION_ERROR", "Invalid artifact_id", artifact_id=artifact_id)

    token_row, identities = _resolve_token_context()
    if token_row is None:
        _log(None, "error", "UNAUTHORIZED", "Token is missing or invalid")
        return _err("UNAUTHORIZED", "Token is missing or invalid")

    rl = _rate_limit_check(token_row)
    if rl:
        _log(token_row, "error", "RATE_LIMIT", rl["error"]["message"])
        return rl

    packages = _load("packages.json")
    if not isinstance(packages, list):
        packages = []
    art = next((r for r in packages if r.get("entity_type") == "artifact" and r.get("id") == artifact_id and r.get("status") != "deleted"), None)
    if art is None:
        _log(token_row, "error", "NOT_FOUND", "Artifact not found")
        return _err("NOT_FOUND", "Artifact not found", artifact_id=artifact_id)

    # FK repo exists and same org
    repo_id = art.get("package_repository_id")
    if not isinstance(repo_id, str) or not repo_id:
        _log(token_row, "error", "CONFLICT", "Artifact missing package_repository_id")
        return _err("CONFLICT", "Artifact is missing package_repository_id", artifact_id=artifact_id)

    repo = next((r for r in packages if r.get("entity_type") == "package_repository" and r.get("id") == repo_id and r.get("status") != "deleted"), None)
    if repo is None:
        _log(token_row, "error", "CONFLICT", "Package repository missing for artifact")
        return _err("CONFLICT", "Package repository does not exist for artifact", artifact_id=artifact_id, package_repository_id=repo_id)

    if repo.get("organization_id") != token_row.get("organization_id") or art.get("organization_id") != token_row.get("organization_id"):
        _log(token_row, "error", "UNAUTHORIZED", "Token not authorized for this artifact")
        return _err("UNAUTHORIZED", "Token cannot access the artifact’s repository")

    now = _now()
    for r in identities:
        if r.get("id") == token_row.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now
            break
    _save("identity.json", identities)

    _log(token_row, "ok")
    return {"artifact": art, "package_repository": repo}

def get_current_identity(api_token, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_current_identity"
    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _ensure_request_log():
        p = os.path.join(_DB, "request_log.json")
        if not os.path.exists(p):
            _save("request_log.json", [])
            return []
        d = _load("request_log.json")
        if not isinstance(d, list):
            _save("request_log.json", [])
            return []
        return d

    def _log(token_row, status, error_code=None, message=None, extra=None):
        logs = _ensure_request_log()
        row = {
            "id": "yunx_req_" + hashlib.sha1(f"{endpoint}:{_now()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "token_id": token_row.get("id") if isinstance(token_row, dict) else None,
            "organization_id": token_row.get("organization_id") if isinstance(token_row, dict) else None,
            "user_id": token_row.get("user_id") if isinstance(token_row, dict) else None,
            "request": {"api_token": api_token if isinstance(api_token, str) else None},
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    if not isinstance(api_token, str) or len(api_token) < 10:
        _log(None, "error", "VALIDATION_ERROR", "api_token must be a string with minLength 10")
        return _err("VALIDATION_ERROR", "api_token must be a string with minLength 10")

    identities = _load("identity.json")
    if not isinstance(identities, list):
        identities = []

    # Authenticate explicit credential by matching client-visible value:
    # - token row id OR token_last4 (if caller passed only last4 or a string ending with last4)
    token_row = None
    for r in identities:
        if r.get("entity_type") != "api_token":
            continue
        if r.get("id") == api_token:
            token_row = r
            break
        tl4 = r.get("token_last4")
        if isinstance(tl4, str) and tl4 and (api_token == tl4 or api_token.endswith(tl4)):
            token_row = r
            break

    if token_row is None:
        _log(None, "error", "UNAUTHORIZED", "Token is missing or invalid")
        return _err("UNAUTHORIZED", "Token is missing or invalid")

    if token_row.get("status") != "active":
        _log(token_row, "error", "UNAUTHORIZED", "Token is not active")
        return _err("UNAUTHORIZED", "Token is not active")

    exp = token_row.get("expires_at")
    if isinstance(exp, str) and exp:
        exp_dt = _parse_dt(exp)
        if exp_dt is not None and exp_dt <= datetime.datetime.utcnow():
            _log(token_row, "error", "UNAUTHORIZED", "Token is expired", expires_at=exp)
            return _err("UNAUTHORIZED", "Token is expired", expires_at=exp)

    uid = token_row.get("user_id")
    oid = token_row.get("organization_id")
    if not isinstance(uid, str) or not uid or not isinstance(oid, str) or not oid:
        _log(token_row, "error", "CONFLICT", "Token does not map to exactly one user_id and organization_id")
        return _err("CONFLICT", "Token must map to exactly one user_id and one organization_id", token_id=token_row.get("id"))

    user = next((r for r in identities if r.get("id") == uid and r.get("entity_type") == "user" and r.get("status") == "active"), None)
    org = next((r for r in identities if r.get("id") == oid and r.get("entity_type") == "organization" and r.get("status") == "active"), None)
    membership = next((r for r in identities if r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("user_id") == uid and r.get("organization_id") == oid), None)
    if not user or not org or not membership:
        _log(token_row, "error", "UNAUTHORIZED", "Token context is not valid for an active user/org membership")
        return _err("UNAUTHORIZED", "Token context is not valid for an active user/org membership")

    # compute simple consumption from request_log
    logs = _ensure_request_log()
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    used_last_min = 0
    for r in reversed(logs[-5000:]):
        if r.get("token_id") != token_row.get("id"):
            continue
        ts = _parse_dt(r.get("timestamp"))
        if not ts:
            continue
        if ts >= cutoff:
            used_last_min += 1

    now = _now()
    # update last_used_at
    for r in identities:
        if r.get("id") == token_row.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now
            break
    _save("identity.json", identities)

    resp = {
        "token": token_row,
        "user": user,
        "organization": org,
        "membership": membership,
        "token_scopes": token_row.get("token_scopes") or [],
        "rate_limit": {"window_seconds": 60, "limit": 120, "used": used_last_min},
    }
    _log(token_row, "ok")
    return resp

def update_change_request_status(api_token, change_request_id, status, merge_commit_message=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0299000" if __import__("os").path.isdir("./environment_mix/0299000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(api_token, str) or len(api_token) < 10:
        return _err("VALIDATION_ERROR", "api_token must be a string with minLength 10")
    if not isinstance(change_request_id, str) or not re.match(r"^yunx_code_[0-9A-Z]+$", change_request_id):
        return _err("VALIDATION_ERROR", "change_request_id is malformed")
    if not isinstance(status, str) or status not in ("open", "closed", "merged"):
        return _err("VALIDATION_ERROR", "status must be one of: open, closed, merged")
    if merge_commit_message is not None and not isinstance(merge_commit_message, str):
        return _err("VALIDATION_ERROR", "merge_commit_message must be a string")

    identities = _load("identity.json")
    token_row = None
    for r in identities:
        if r.get("entity_type") != "api_token":
            continue
        if r.get("id") == api_token or r.get("token_last4") == api_token[-4:]:
            token_row = r
            break

    reqlog = _load("request_log.json")
    if not isinstance(reqlog, list):
        reqlog = []

    def _log(status_code, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        req = {
            "id": "req_" + hashlib.sha1((now + str(time.time())).encode("utf-8")).hexdigest()[:16],
            "endpoint": "update_change_request_status",
            "timestamp": now,
            "status": status_code,
            "latency_ms": latency_ms,
            "organization_id": token_row.get("organization_id") if token_row else None,
            "user_id": token_row.get("user_id") if token_row else None,
            "api_token_id": token_row.get("id") if token_row else None,
        }
        if error_code:
            req["error_code"] = error_code
        reqlog.append(req)
        _save("request_log.json", reqlog)

    if token_row is None:
        _log(401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token is missing or invalid")
    if token_row.get("status") != "active":
        _log(403, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token is not active")
    exp = token_row.get("expires_at")
    if isinstance(exp, str) and exp:
        try:
            exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00"))
            if exp_dt <= datetime.datetime.now(datetime.timezone.utc):
                _log(401, "UNAUTHORIZED")
                return _err("UNAUTHORIZED", "Token is expired")
        except Exception:
            pass

    # rate limit 120/min
    try:
        window_start = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0)
        token_id = token_row.get("id")
        recent = 0
        for r in reqlog:
            if r.get("api_token_id") != token_id:
                continue
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    ts_dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
                    if ts_dt >= window_start:
                        recent += 1
                except Exception:
                    continue
        if recent >= 120:
            _log(429, "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded")
    except Exception:
        pass

    org_id = token_row.get("organization_id")
    user_id = token_row.get("user_id")
    if not org_id or not user_id:
        _log(401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token is not bound to a user and organization")

    codeup = _load("codeup.json")
    cr = None
    cr_idx = None
    for i, r in enumerate(codeup):
        if r.get("id") == change_request_id and r.get("entity_type") == "change_request" and r.get("status") != "deleted":
            cr = r
            cr_idx = i
            break

    if cr is None:
        _log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "Change request not found")

    if cr.get("organization_id") != org_id:
        _log(403, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not permitted to update this change request")

    # Require active membership for user in org
    has_membership = False
    for r in identities:
        if r.get("entity_type") == "membership" and r.get("status") == "active" and r.get("organization_id") == org_id and r.get("user_id") == user_id:
            has_membership = True
            break
    if not has_membership:
        _log(403, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active membership in organization")

    # Validate transition per lifecycle for codeup: open->merged/closed, closed->open, merged terminal
    current = cr.get("status")
    allowed = {
        "open": {"closed", "merged"},
        "closed": {"open"},
        "merged": set(),
        "deleted": set(),
    }
    if current not in allowed:
        _log(409, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Current status does not support transitions", current_status=current)
    if status == current:
        # idempotent update: no mutation required but still should reflect "no success without effect"?
        # Here, treat as success only if it matches row (effect is none); vendor APIs usually accept idempotent set.
        _log(200)
        return {"change_request": cr, "idempotent": True}
    if status not in allowed[current]:
        _log(409, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Invalid status transition", current_status=current, target_status=status)

    # Apply transition
    cr["status"] = status
    cr["updated_at"] = now
    # When merging, optionally record merge message into description append (since schema has no field)
    if status == "merged" and merge_commit_message:
        desc = cr.get("description") or ""
        note = "\n\n[merge_commit_message] " + merge_commit_message
        cr["description"] = desc + note if desc else note.lstrip("\n")

    codeup[cr_idx] = cr
    _save("codeup.json", codeup)

    # Update token usage
    token_row["last_used_at"] = now
    token_row["updated_at"] = now
    for i, r in enumerate(identities):
        if r.get("id") == token_row.get("id") and r.get("entity_type") == "api_token":
            identities[i] = token_row
            break
    _save("identity.json", identities)

    _log(200)
    return {"change_request": cr}
